INSERT INTO public.locations (id, name, image, description, address, google_maps_link, city_id) VALUES ('988m36yqy', 'Forest City Brewery', 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1781734282995-forest_city.webp', '"Where old meets brew". An old school microbrewery located in a historic 100 year-old building.  The Beer Garden was recently ranked one of the top in the country.  RBL Cleveland runs shows in the main hall and side rooms.', '2135 Columbus Rd', 'https://maps.app.goo.gl/xeeWfGixp7JexsT1A', '34R1xSji5u4ZORWkNetI') ON CONFLICT (id) DO NOTHING;
