INSERT INTO public.locations (id, name, image, description, address, google_maps_link, city_id) VALUES ('kf0rl3wgt', 'Funny Stop Comedy Club', 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1781734520170-funnystop.webp', 'The Funny Stop Comedy Club was Cuyahoga Falls'' destination for live stand up comedy from the early 2000''s after it moved from Hilarities South until its closure in 2026.  It was run by Pete Barakat, who was legendary amongst patrons and comedians, until his death in 2024.   Everyone who''s ever been there has an impression of him telling someone off or FIVE MEENUTS, CLEAN MATERIAL.  His wife Nidal ran the club along with his brother Tony until its closure.', '1757 State Rd', 'https://maps.app.goo.gl/XtkY6bvEoSmbkgF47', '34R1xSji5u4ZORWkNetI') ON CONFLICT (id) DO NOTHING;
