INSERT INTO public.locations (id, name, image, description, address, google_maps_link, city_id) VALUES ('o04y9rchw', 'Funny Farm Comedy Club', 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1781734699213-funny_farm.webp', 'For 37 years, the Funny Farm has been Youngstown''s premiere comedy destination across multiple locations.  Owner Dave Robich brings a mix of legends and locals to the stage every weekend.', '4422 Youngstown Road SE', 'https://maps.app.goo.gl/JFFsruodYp9DLhyQ8', '34R1xSji5u4ZORWkNetI') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.locations (id, name, image, description, address, google_maps_link, city_id) VALUES ('artlbssof', 'Spotlight Cleveland', 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1781736425878-spotlight.webp', 'Spotlight Cleveland is a classic "corner bar" hosting live performances seven nights a week.  Opened in 2023 by co owners Corinne and Dewey, Spotlight was RBL Cleveland''s first home after joining the league in 2024.', '8701 Madison Ave', 'https://maps.app.goo.gl/Wp76UaLwr7jsveav9', '34R1xSji5u4ZORWkNetI') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.locations (id, name, image, description, address, google_maps_link, city_id) VALUES ('gicjvuq3i', 'Tokyo Comedy Bar', 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1780714033794-Tokyo_Comedy_Bar_Stacked_White_L.webp', 'Tokyo Comedy Bar is Japan’s home of stand-up comedy, offering shows in English and Japanese every night. Founded by local comedians, now we run two shows nightly, plus comedy courses for anyone who wants to try their hand at stand-up, with craft beer on tap to keep the good times flowing. Over the past few years, we’ve welcomed thousands of visitors, launched performers internationally, and brought top comedy acts from the U.S., U.K., and beyond. Our mission is simple: make stand-up a part of Japan’s live entertainment scene and give everyone a place to laugh, relax, and connect.', '3rd floor, 1-chōme-5-9 Dogenzaka, Shibuya, Tokyo', 'https://www.google.com/maps/place/tokyo+comedy+bar/data=!4m2!3m1!1s0x60188b7fd0219b2d:0x2e6dc888bec78eb0?sa=X&ved=1t:242&ictx=111', 'NIeTzbnILTHvU69T33i3') ON CONFLICT (id) DO NOTHING;
