INSERT INTO public.locations (id, name, image, description, address, google_maps_link, city_id) VALUES ('g0ye6qreb', 'Happy Dog', 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1781734255735-happy_dog.webp', 'The Happy Dog is a corner bar/hot dog shoppe/concert venue in Cleveland''s Gordon Square Neighborhood established under current ownership in 2008.  They have performance spaces upstairs and in the basement in the Underdog.  Happy Dog has played host to many comedy shows over the years including Keep Talking with Zachariah Durr and Adam Richard, Modern Kicks with Jimmie Graham and the comedy portion of artist Derek Hess'' Acting Out Festival.  They are best known for their insane hot dog toppings and being a great place to catch local and touring bands.', '5801 Detroit Ave', 'https://maps.app.goo.gl/ijwDnWXxsF4oaRLd8', '34R1xSji5u4ZORWkNetI') ON CONFLICT (id) DO NOTHING;
