INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('sg2Z1iy3VF6dGL5UPOtq', 'Chris Crespo', 'Male', 'Hispanic', 1000, 'cresposts', 'Meet the man who can fire off five shots at a roast battle, but can’t give you a proper high five. Christopher Crespo is a NYC comedian from NJ. He’s the author of the self published horror novel, “Boy Meets Corpse”. He was one of the original roasters of Roastmasters at The Stand, who went toe to toe with Eli Sairs. Crespo has battled at The Comedy Mothership, The Stand, Grove 34 & The Comedy Cellar. ', TRUE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1778978472777-battler.webp', 'za2nHt1bzRQ0xgVRbCg2') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
