INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('1umourttw', 'Tommy Flanigan', 'Male', 'White', 1000, 'tommyflanigan_', 'Tommy Flanigan is a Lexington, KY based stand up comedian that takes his high energy performances and breaks down dating, teaching, family, and … jail? Tommy can frequently be seen at The Spot as well as being a regular on encore shows all around Kentucky. He has preformed on Don’t Tell Comedy, opened for Leyla Ingalls, and he is writing out the lesson plan to open for my comics in the future (it’ll be late, as per usual). Tommy’s passion for comedy doesn’t stop at stand up, he is also a sketch comic who, as a co-founder and creator on Spilled Milk Media, brings laughter to people not only from a stage but from their own phone screen.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1783279007836-Tommy-Flanigan.webp', 'AHjyLmocgSHDrs8Bj4fd') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('btu5u2n0e', 'Simon Atkinson', '', '', 1000, 'Simon_and_102_others', 'Simon Atkinson is an Orlando-based stand-up comedian, filmmaker, and casual poet who hit the comedy stage after realizing his college degree wasn''t going to pay for itself. Armed with a sharp wit and a healthy dose of post-grad existential dread, Simon has quickly become a familiar face in the Central Florida comedy scene.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1783649084085-Simon-Atkinson.webp', '656eopzhh') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
