INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('newg1sinm', 'Derek Stacy', 'Non-binary', 'White', 1000, 'derekstacycomedy', 'Derek Stacy is a  Lexington, KY based stand up comedian. Who has been performing since they were a senior in high school. Derek takes a blend of observational comedy, storytelling, satire, and self-deprecation turning it into a high energy performance. Derek has taken their talents to shows across Kentucky, North Carolina, Ohio, Pennsylvania, and West Virginia. Along the way Derek has been given the opportunity to open for Liam Nelson, Caitlyn Reese, Kevin Casey White, Zac Amico, and Pauley Shore. Derek  has also. spent most of their time in comedy producing and running shows including open mics at local breweries, overflowing house shows, and even sold out shows for touring comics. One of these shows Derek is proudest of is the recording of their mini special “I Swear Everything is Fine”  out now!', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1783281651661-Derek-Stacy.webp', 'AHjyLmocgSHDrs8Bj4fd') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('c0lgru4au', 'Joe Censabella', '', '', 1000, 'joecomedyy', 'Joe Censabella, known on stage and online as Joe Comedyy, is one of Central Florida’s most dynamic and relentless comedians. A true fixture of the Orlando comedy scene, Joe built his reputation on high-energy delivery, quick-fire wit, and an unfiltered approach to storytelling.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1783649396574-Joe-Censabella.webp', '656eopzhh') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
