INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('8us9cpngb', 'Raul Kohli', 'Male', 'Indian', 1000, 'raulkohlicomic', 'Raul Kohli is an English stand-up comedian and broadcaster from Newcastle upon Tyne. He initially performed as Rahul Kohli, but changed his stage-name to differentiate himself from the actor with the same name. He won the NATYs award in 2017, and was nominated for Best Show at the ISH Edinburgh Comedy Awards in 2024.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1785013027584-Raul-Kohli.webp', 'P2ONL89ZfvaLZ1Ged5hC') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
