INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('0x4p4kpo6', 'Jeremy Sheer', 'Non-binary', 'White', 1000, 'dirtysheer', 'Jeremy is a co-producer for Roast Battle Cleveland, co-produces Sketch Battle, a seasonal Sketch Comedy competition, co-hosts Crap Radio on XCSB Cleveland and co-hosts Let The Hate Flow Through You, a specific general interest podcast.  There is a lot to unpack here, and each opponent does so one battle at a time.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1781909409260-Jeremy-Sheer.webp', '34R1xSji5u4ZORWkNetI') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
