INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('qcq9z1epw', 'Tony Wellons', '', '', 1000, 'thetonywellons', 'Tony Wellons is a rising stand-up comedian based in Austin, Texas, originally hailing from Orlando, Florida. With nearly seven years of experience, Tony has established himself in the comedy scene by captivating audiences across the country with his unique blend of humor and charm.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1783649630308-Tony-Wellons.webp', '656eopzhh') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
