INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('squtnlpcw', 'Audrey Hebert', 'Female', 'White', 1000, 'audreyhebertonline', 'Bio: Audrey Hebert is a Los Angeles-based standup comic and roast battler. She won the 2025 San Diego One Liner Madness competition and has battled at the Comedy Store, the Comedy Mothership, and the Comedy Cellar.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1784656487919-Audrey-Hebert.webp', 'EzOfMEwWjCcQ7OF6lHb9') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('dmn6qv2vl', 'Brian Smiley', 'Male', 'White', 1000, 'briansmiley_', '', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1784774650583-Brian-Smiley.webp', 'm8qfn6yjl') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('8kqkyit06', 'Gylije Veljic', 'Female', 'White', 1000, 'gyllije', 'Gylije Veljic is a global advertising executive, comedy producer, podcast host, and living proof that crippling narcissism can be wildly productive. She’s produced shows for the New York Comedy Festival, opened for DC Benny and Eleanor Kerrigan, and was a Maxim Cover Girl finalist—which is incredibly exciting if you’re a white guy over 50 from Kentucky. Her comedy is so honest and so wildly enthusiastic about her worst decisions, she’ll have you leaving the show wondering if jail was actually… kind of fun.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1784857984981-Gylije-Veljic.webp', 'za2nHt1bzRQ0xgVRbCg2') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('dmqbnrlq9', 'Lizard', 'Female', 'White', 1000, 'lizard.haha', '', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1786831612540-lizard.webp', 'kirz803kr') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('8kr8iv7pl', 'Saleha Masud', 'Female', 'Other', 1000, 'saleha.masud', 'Saleha Masud serves up fearless, sharply observed stand-up from a proudly Muslim perspective, blending cultural insight with punchlines that land hard and fast – all with the added lens of single parenthood. A West End New Act of the Year 2023 finalist, she’s now a regular Roast Battler and judge at the late night Roast Battle show at Angel’s Bill Murray Comedy Club, where her professional level shit talking is not only a crowd favourite but also, as she puts it, very effective for keeping her coparent in check. By day she’s a litigation lawyer; by night she brings bold takes, bright energy and the kind of set that leaves jaws dropped and audiences grinning. ', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1785013408261-Saleha-Masud.webp', 'P2ONL89ZfvaLZ1Ged5hC') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('7gjfetcek', 'James Mileham', 'Male', 'White', 1000, 'jamesmileham', 'James Mileham is a sharp-witted comedian with a knack for crafting punchlines that stick. Based in London, he regularly performs at top comedy clubs across the UK, delivering joke-packed sets that keep audiences engaged from start to finish.
