INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('rkpbwfjte', 'Vance Dykes', '', '', 1000, 'vancedykes', 'Vance Dykes is an Orlando-based ventriloquist who blends stand-up comedy with unforgettable puppet characters. Best known for his fan-favorite zombie puppet, Zombie Bush, Vance delivers a unique mix of sharp comedy, clever banter, and spooky fun that keeps audiences laughing from start to finish. With a style that''s equal parts classic ventriloquism and modern comedy.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1783476840610-Vance-Dykes.webp', '656eopzhh') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('n42k3xgry', 'Cee Dillard', '', '', 1000, 'ceedillard_', 'Cee Dillard is a rising comedian in the Central Florida comedy scene, known for his laid-back stvle and sharp wit. Whether he''s riffing with intimate audiences or tackling the quirks of life as a local comic. Cee brings an unfiltered perspective to the mic.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1783650170827-Cee-Dillard.webp', '656eopzhh') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
