INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('r1atxofi8', 'Jim Florentine', 'Male', 'White', 1000, 'jimflorentine', 'Gutfeld Show. Kill Tony. Radio Show on SiriusXM. Preorder Terrorizing Telemarketers Vol 8 out 9/18. Podcast is Everybody Is Awful.', FALSE, FALSE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1786813095411-jim-florentine.webp', 'za2nHt1bzRQ0xgVRbCg2') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('rjaq4g1qv', 'Mike Haha', 'Male', '', 1000, 'Mike.haha', 'Mike Haha is an Orlando-based comedian whose years of life experience fuel his sharp observations, quick wit, and effortless storytelling. With a laid-back stage presence and a knack for finding the humor in everyday situations, Mike connects with audiences of all ages through relatable, honest comedy. Whether he''s sharing stories about getting older, family life, or the absurdity of modern living, Mike delivers laughs with the confidence that only experience can bring.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1783475996074-Mike-Haha.webp', '656eopzhh') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('ct8j50s29', 'Tae TattedUpp', '', '', 1000, 'taetattedupp', 'Tae TattedUpp is an independent stand-up comedian, high-energy host, and digital content creator who commands the stage across the Florida comedy circuit. Known as a powerhouse in late-night entertainment, she brings an unfiltered and magnetic presence to live audiences.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1783650677820-Tae-TattedUpp.webp', '656eopzhh') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('69yfcmb6q', 'Free Rodriguez', 'Male', 'Hispanic', 1000, 'free80four', '"Free is a conservative Dominican. You could call him a Dominican Republican" — Bill Miller. The lean, mean, fútbol loving Latino is here! Free is also a regular organizer of Spanish-language comedy events around Tokyo.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1781014839471-Free-Rodriguez.webp', 'NIeTzbnILTHvU69T33i3') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
