INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('bmlilen2d', 'Amir Schuman', '', '', 1000, 'amereshoeman', 'Amir Schuman is a Jacksonville-based comedian whose raw, honest style turns everyday observations into unexpected laughs. Drawing from a Zillennial perspective, he explores culture, identity, and modern life with sharp storytelling that keeps audiences laughing while questioning their own assumptions.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1783475281751-Amir-Schuman.webp', '656eopzhh') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('6x8kd50ju', 'Laila Shaykhian', '', '', 1000, 'laughoutlaila321', 'Laila Shaykhian (known to her online fans as @laughoutlaila321) is a high-energy stand-up comedian and digital creator making major waves across the Florida comedy circuit. Proving that it is never too late to chase a lifelong dream, Laila took a bold leap onto the stage at age 37 after completing intensive stand-up training—and she hasn''t looked back since.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1783650794123-Laila-Shaykhian.webp', '656eopzhh') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
