INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('49asr2fkp', 'Senneca Stone', 'Male', 'White', 1000, 'sennecastone', 'Senneca Stone is a comic from Pittsburgh, PA who regularly performs at Improv and Helium Comedy Clubs. He was a featured performer at the Toronto Dark Comedy Festival and a Finalist in the Pittsburgh Comedy Festival Stand Up Competition. He was also named a "Budding Star" in Helium Comedy Club’s national promotion and hosts a monthly showcase for the Pittsburgh Improv showcasing comedians from cities in the Rust Belt. Senneca’s comedy is about having a good time and making fun of his dysfunctional upbringing.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1786813189468-senneca-stone.webp', 'AHjyLmocgSHDrs8Bj4fd') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('6n3lf0bup', 'Alysa Browne', 'Female', 'White', 1000, 'alysabrowne', 'Alysa Browne is a Brooklyn-based comedian and 2024 Ladies of Laughter finalist. She has appeared in the New York Comedy Festival, Finger Lakes Comedy Festival, Windy City Comedy Festival, and co-produces the monthly NYC show Hot Chips Comedy', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1785792719759-alysa-browne.webp', 'za2nHt1bzRQ0xgVRbCg2') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
