INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('TCMSbOMZRuI9ZANZPmsR', 'Greg Giraldo Jr', 'Male', 'White', 1000, 'greggiraldojr', 'Greg Giraldo jr currently competes out of New York City, recently roasted at the comedy cellar, and is a regular at RBL’s weekly shows. He also is a nepo baby with a dead dad (Greg Giraldo) making him a second generation roaster (derogatory). When not roasting you can catch him doing regular standup spots around New York City and throughout the country ', TRUE, TRUE, 3, 2, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1778818043812-battler.webp', 'za2nHt1bzRQ0xgVRbCg2') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
