INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('4mrzqp2mi', 'Bobby Jaycox', '', '', 1000, 'bobbyjaycox', 'A stand-up comedian and actor based in St. Louis, Bobby Jaycox is one of the funniest voices in the Midwest today, performing at comedy clubs and colleges across the country. His fun energy both on and off stage, strong writing and professionalism have earned him spots opening for stars, such as Dave Chapelle, Natasha Leggero, Nikki Glaser, Rory Scovel, and Brian Regan, in addition to performances on the road with comics Carly Aquilino and Taylor Williamson. Bobby’s material pulls from his real-life experiences as a firefighter and EMT, past relationships, wildly embarrassing moments and the absurd. ', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1783475517820-Bobby-Jaycox.webp', '656eopzhh') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('hslscg7zk', 'Selena Ubias', '', '', 1000, 'selena.ubias', 'Selena Ubias is a rising stand-up comedian and digital creator known for her punchy, unfiltered storytelling. After breaking into the Central Florida comedy scene in 2023, she gained national attention with a standout, breakout performance on the hit live-streamed show Kill Tony.Now based in Austin, Texas, Selena regularly shares her chaotic, self-deprecating humor on stage and as the co-host of the Unstable Creatures Podcast. Her comedy hilariously tackles the absurdities of daily life, dating, body image, and the wild hustle of a traveling comic.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1783651023648-Selena-Ubias.webp', '656eopzhh') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
