INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('1aku7tjkm', 'King Quelz', '', '', 1000, 'king.quelz', 'King Quelz is a high-energy, animated Florida based comedian by way of Jacksonville, Fl. Quelz began his career in Orlando, Fl a week before the Covid pandemic doing a couple of local open mics. In the summer of 2020, after being invited to watch a comedy show by a fellow comedian, Quelz was invited on stage & was instantly invited to join a tour as an opener headed by TikTok & Instagram sensation, Justin Silva. Now, touring the country again, King Quelz continues to expand his versatility & originality in his art bringing much needed gut-cramping laughter to a broken world. With quick wit, detailed animations, & layered storytelling, Quelz aspires to inspire the world with humor and unique perspectives on life to be the best versions of themselves.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1783475654552-King-Quelz.webp', '656eopzhh') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('2s3rzw4i7', 'Ivin B. Propain', '', '', 1000, 'ivinb_propain', 'Ivin B. Propain is a stand-up comedian, host, and emcee based out of Melbourne, Florida. Known for his quick wit and high-voltage stage presence, Ivin has become a favorite fixture across the Central Florida comedy scene.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1783651417465-Ivin-B.-Propain.webp', '656eopzhh') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
