INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('tfe49ol45', 'CJ Koepp', 'Female', 'White', 1000, 'cjkoepp', 'CJ Koepp is a Wisconsin-raised, New York-based writer, activist, and stand-up comedian. She''s opened for comedians Nick Kroll, Irene Tu, and Dave Attell. CJ been featured in Pixar''s "Hoppers," SF Sketchfest, Reductress'' Best of 2025 collection and comedy clubs across the country. She has been awarded the 2026 St. Nell''s Comedy Writing Residency, the 2025 Killing My Lobster New Voices in Comedy Writing Fellowship, and won first runner-up in the 2025 San Francisco International Comedy Competition.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1786166474156-cj-koepp.webp', 'za2nHt1bzRQ0xgVRbCg2') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
