INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('d2xbtdmum', 'Carson Taylor', 'Male', 'White', 1000, 'carsontaylorcomedy', 'Carson Taylor is a stand-up comedian from Mobile, Alabama, with over a decade of experience performing throughout the Southern United States. His comedy style blends observational humor, self-deprecating storytelling, and sharp one-liners, creating a voice that’s both original and relatable. Carson is also a co-producer of Whipper Snapper Comedy and hosts weekly open mics in Mobile, AL, helping grow the Gulf Coast comedy scene!', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1784341414035-Carson-Taylor.webp', 'kirz803kr') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('8rglqn48k', 'Yoky Yu', 'Female', 'Asian', 1000, 'yoky_yu', 'Yoky Yu is a professional therapist, comedian and writer based in Barcelona and online. Yoky works psychosomatically with clients located in and/or originated from Europe, Asia, North America, South America, Africa and Australia. I have worked and lived in China, U.S.A, and now Spain. (LGBTQ+ member; cross-culturally trained.) Her last name 俞 in ancient Chinese means “healing”, which is pretty much her calling for life.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1785018379690-Yoky-Yu.webp', 'AnngcYMoHFDZK7U2xDBV') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
