INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('laefzac3k', 'Dean T. Beirne', 'Non-binary', 'White', 1000, 'deantbcomedy', 'Dean T. Beirne is a comedian and writer from Glasgow. With an innate passion for storytelling, Dean''s journey into comedy progressed quickly, having reached the semi-finals of the Chortle Student Comedy Award 2023 on a wildcard entry. Dean''s razor-sharp wit, fresh voice, and charismatic stage presence earned him recognition as a rising star in the comedy world.
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('n2wq71g0y', 'Dave Sirus', 'Male', 'White', 1000, 'davesirus', 'Dave Sirus, a Brooklyn-based comedian and writer, spent many years struggling to reach the success that he has now arguably achieved. For years Dave toiled away in the LA comedy scene and on YouTube not knowing that somewhere out there, a tragedy-stricken little boy who would someday grow up to be Saturday Night Live and Manscaped commercial star Pete Davidson would eventually make his dreams come true. Partnering with Davidson on projects like Bupkis, The King of Staten Island and Roasts, as well as with Triumph the Insult Comic Dog on Hulu, Comedy Central, CBS, and FOX, Dave has finally achieved as much success as anyone in the current state of the entertainment industry could possibly hope for.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1781458502591-Dave-Sirus.webp', 'za2nHt1bzRQ0xgVRbCg2') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('2wegTFWZwMwJ15WddEQg', 'Rania Hannan', 'Female', 'Middle Eastern', 1000, 'bigcvntry', 'Rania grew up with three mean older sisters so she''s heard it all before. Before moving to New York, she lived in a van for three years traveling the country with her old ass dog. She runs a monthly comedy dating show called "Do You Still Like Me" where she''s doing god''s work helping comedians find love.', TRUE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1778818096621-battler.webp', 'za2nHt1bzRQ0xgVRbCg2') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
