INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('25ltxepwz', 'Ivi Demi', 'Male', 'White', 1000, 'ivi.demi', 'Bio: Ivi is a Brooklyn comic originally from Albania. When he''s not busy maintaining his nation''s proud tradition of trafficking human beings, he''s performing regularly at the DC Improv, Comic Strip, Bushwick Comedy Club, and Rodney''s. If you see him smoking outside a venue, there''s now a comedy show there.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1781496603823-Ivi-Demi.webp', 'za2nHt1bzRQ0xgVRbCg2') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('0usdnk4ig', 'Jordan Leung', 'Male', 'Asian', 1000, '69ranch', 'Jordan Leung is a Hong Kong American comedian who has sold out international tours across Asia, Europe, and Australia. His dry humor has built him a cult following in the Cantonese diaspora, but Jordan is still funny even if you aren''t Asian, according to his non-Asian friends.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1782197671656-Jordan-Leung.webp', 'za2nHt1bzRQ0xgVRbCg2') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
