INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('lrjys2xfr', 'Lauren Gamiel', 'Female', 'White', 1000, 'thatgamielgirl', 'Lauren is a performer, writer, director and musician based in NYC. Her work has been featured internationally at the Venice International Film Festival and Edinburgh Fringe Festival, in NYC at the Upright Citizens Brigade Theater, the Peoples Improv Theater, the Magnet Theater, and more. Lauren is a regular performer in the sketch, character and stand up comedy community of NYC, as well as an active director and coach. Her dream roles include Comedic Relief in any fantasy series with dragons and Lord Farquaad in Shrek the Musical', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1784996795207-Lauren-Gamiel.webp', 'za2nHt1bzRQ0xgVRbCg2') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('249cn9011', 'Madison Thomas', 'Female', 'Black', 1000, 'madtomcom', 'Madison Thomas is a stand-up comedian, writer, and actor originally from New Orleans and currently based in Baton Rouge. She is the 2024 New Orleans Roast Battle Champion and has performed with Don''t Tell Comedy in New Orleans, Detroit, and Grand Rapids. Her festival credits include LGBTQLOL, Toledano Street Comedy Festival, Lunchbox Comedy Festival, and the Detroit Women of Comedy Festival.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1784342253727-Madison-Thomas.webp', 'kirz803kr') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('8jg54a6t5', 'Mark Caesar', 'Male', 'Black', 1000, 'mark_caesar', 'Mark Caesar is a stand up comedian from New Orleans La. In 2009 Mark Caesar started Piss Yo Pants Comedy and put together a string of successful comedy shows in the following months and to this day. Mark Caesar also is host to the number one comedy show in the greater New Orleans area "Laugh and Sip" which is every Thursday night at The Wine Bistro 1011 Gravier st.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1784342390425-Mark-Caesar.webp', 'kirz803kr') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
