INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('ifsin8hrh', 'Helen K', 'Female', 'White', 1000, 'hel_hath_no_fury', 'Helen K describes herself as a stand-up with a menacing aura and a heart of gold. In her comedy, Helen talks about being born and raised in Russia, the dick move that is the invasion of Ukraine, and broader social issues – all while subverting obvious stereotypes.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1784343117004-Helen-K.webp', 'P2ONL89ZfvaLZ1Ged5hC') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('nr12afha6', 'Tyler Arceneaux', 'Male', 'White', 1000, 'thetylera', 'Originally from Lafayette, Louisiana, Tyler Arceneaux is a comedian with a dozen years of experience. He has traveled across the country telling jokes from his perspective as a single millennial parent living in the South. Tyler has opened for national touring comedians Mark Normand, Jeff Dye, Robert Kelly, Joe DeRosa, Luis J. Gomez, Sean Patton, Sam Tallent, and Caitlin Peluffo. He has been featured on several comedy festivals such as Skankfest and Altercation Comedy Fest. Tyler also hosts the "We''re Dying Down Here" podcast, where he and his co-host, JP Leonard, have conversations with national touring comedians.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1785032962862-Tyler-Arceneaux.webp', 'aSxmOdOxVsemCTuQJny3') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('c32r7clso', 'Sophie Corbett', 'Female', 'White', 1000, 'sophie_corbs', 'Sophie Corbett is an up and coming stand-up comedian from Denver, Colorado. When she is not on stage, she is usually at work in an animal hospital. You can find her performing at Greenwich Village Comedy Club, Haylard’s, and Broadway Comedy Club.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1785947789868-sophie-corbett.webp', 'za2nHt1bzRQ0xgVRbCg2') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
