INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('buku72zqa', 'Brian Rabadeau', 'Male', 'White', 1000, 'brabs91', 'Brian Rabadeau is a comedian who''s been performing in the NY/NJ area for longer than he cares to admit. Recent highlights included performing as a part of the Hell Yes Festival, Montclair Comedy Festival, and the Jersey City Comedy Festival. His career highlight was headlining the Tokyo Comedy Bar in 2022. He''s gay, from New Jersey, and was told he looked like a character in a "fucked up version of the movie Clerks." ', FALSE, TRUE, 0, 1, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1782942842605-Brian-Rabadeau.webp', 'za2nHt1bzRQ0xgVRbCg2') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
