INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('urnm53ly0', 'Zachary Hendrick', '', '', 1000, 'zacharyhendrickcomedy', 'Zachary is a Florida-based stand-up comedian known for his quick wit, relatable storytelling, and laid-back stage presence. Whether he''s hosting, featuring, or headlining, Zachary delivers an effortless style that keeps audiences laughing and coming back for more.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1783477635063-Zachary-Hendrick.webp', '656eopzhh') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('EUR2p7XGewQBk8NxlQLC', 'Fluke Human', 'Male', 'White', 1000, 'flukehuman', 'Fluke Human is a comedian from NYC who has done an unhealthy amount of roast battling. His wide variety of hobbies he is bad at (rapping, skateboarding, DJing, calisthenics) makes him a fun opponent with a lot of roastability. He also posesses the unique ability to memorize 5 jokes, giving him an edge in stage presence and charisma. He spends most of his battles talking about himself, the judges, and really anyone besides his actual opponent. ', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1779843219253-battler.webp', 'za2nHt1bzRQ0xgVRbCg2') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
