INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('NoG0lCPPRDXriEqWG065', 'Big T', 'Male', 'White', 1000, 'bigtitsbigpics', 'Big T is your favorite uncle. A native New Yorker who got started in roasting in kindergarten in the public schools of Brooklyn, he loves to say whatever he''s thinking. He cares about equality so everyone gets it. He doesn’t care what you think because he’s the people’s champ. And he thinks he’s better than you because he owns an above ground pool. Make it make sense!!!', TRUE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1779263450628-battler.webp', 'za2nHt1bzRQ0xgVRbCg2') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
