INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('zrai2hfg2', 'Ryne DiPerna', 'Male', 'White', 1000, 'rynediperna', 'Ryne DiPerna is one of the cofounders of RBL Cleveland when it was the Ad Hominem Attack Show in 2016.  He was a part of sketch group Pizza Money where his Ill Timed Pizza Delivery Guy sketch achieved some acclaim.  He is best known for his leftist rants and his hero worship of Norm MacDonald.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1783206828015-Ryne-DiPerna.webp', '34R1xSji5u4ZORWkNetI') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('fr38mazn5', 'Avery Gordon', '', '', 1000, 'averygordoncomedy', 'Avery Gordon is a Florida-based stand-up comedian known for his dark humor, sharp wit, and laid-back delivery. With an unapologetic style and a knack for finding laughs in unexpected places, Avery brings a unique perspective to every stage he steps on.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1783477934391-Avery-Gordon.webp', '656eopzhh') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
