INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('3fygys1kw', 'Connor O''Brien', 'Male', 'White', 1000, 'obz', 'Connor O’Brien came onto the roast battle scene when he won the 2025 Comfy Cook-Off at the Comic Strip Live! He has also performed roast battles at the Comedy Cellar, Comedy Mothership, and New York Comedy Club. Connor roasts in Hartford, CT and New York City, where he brings his own unique style to his battles. While he may look and sound “roasted” himself, Connor is completely sober, and his non-threatening, chill approach to roasting can quickly surprise his opponents, and take them down like a black widow spider. In nature, the color red is a sign to beware, Connor’s red hair is no different, his nonchalant rebuttals allow his opponents jokes to roll right off, almost as if he is covered in baby oil, but he doesn’t even use baby oil or lotion, he is just naturally smooth.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1780006768389-battler.webp', 'dOfXYBu8N1KovWgOiLZ5') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
