INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('hd2wtlrmy', 'Dylan Lusk', 'Male', 'White', 1000, 'dylanlvsk', 'Dylan co hosts the Pun So Vile podcast and is available for all of your tech needs if you''re putting together anything of substance.  When he is not working on a film, television or podcast production, Dylan can be found hosting some of LA''s hottest showcases and upsetting someone with his musical opinions.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1790639727588-dylan-lusk.webp', 'EzOfMEwWjCcQ7OF6lHb9') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
