INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('rzzejvjk9', 'Paul Beel', 'Male', 'White', 1000, 'paulbeelartncomedy', 'Paul Beel received his BFA and MFA from the School of Art at Bowling Green State University, Ohio.  He did Post-Baccalaureate work at Studio Art Centers International, Florence, Italy, where he later taught painting and drawing. He has had solo shows in Venice, Milan, Florence, Mantova, as well as in the US, and group shows in Spain, Germany, San Marino, Switzerland, London, and throughout Italy.  His work has won awards and critical attention, and is sought out for its rarity, technical brilliance and uncompromising revelation of the human condition by his avid collectors.  He now performs stand up comedy with accompanying pictures in Cleveland, OH.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1783208401923-Paul-Beel.webp', '34R1xSji5u4ZORWkNetI') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('hyaenyds3', 'Gene Meyer', '', '', 1000, 'genemeyerlol', 'Gene Meyer is a Florida-based stand-up comedian known for his quick crowd work, sharp observations, and easygoing stage presence. Blending clever storytelling with a playful sense of humor, Gene delivers a fun, engaging set that connects with audiences wherever he performs.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1783478034106-Gene-Meyer.webp', '656eopzhh') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
