INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('2CKUaDcqdZPHsjFeQf4v', 'Michael Agunbiade', 'Male', 'Black', 1000, 'agunbreezy', 'Michael Agunbiade is a New York based veteran comedian that proves not all cool Black guys get bitches. After enduring 3 years of the Upstate NY comedy scene he’s finally made his way back down towards another STD filled cesspool (The Bronx) to compete with some of the greatest  roast comics NYC has to offer. With a notebook filled with tons of pop culture references and cringey act outs watch him set the stage and prove once for all, Black people can be racist too. ', TRUE, TRUE, 5, 3, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1780936688231-Michael-Agunbiade.webp', 'za2nHt1bzRQ0xgVRbCg2') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('4eKZ1TPSknEdcrUFErjH', 'Mike Gamms', 'Male', 'White', 1000, 'mikegamms', 'Originally from Rochester, NY, Mike Gamms is the Roast Battle League''s biggest loser. This traveling punching bag has battled in cities all over the country, and lost in them all. A loser on and off the stage, not even his beloved Buffalo sports teams lose as much as this guy.', TRUE, TRUE, 0, 1, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1779308974706-battler.webp', 'za2nHt1bzRQ0xgVRbCg2') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('bu050x9gj', 'Eric Taylor', 'Male', 'White', 1000, 'futr2brite', 'Eric Taylor is a former Absolute Intense Wrestling Absolute Champion and Intense Champion.  He has won multiple tag titles as part of The BitcoinboiZ.  ', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1790640390184-eric-taylor.webp', '34R1xSji5u4ZORWkNetI') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
