INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('p9bIaVTNqlzIU3mxu7cu', 'Dan Wickes', 'Male', 'White', 1000, 'dan_wickes', 'What could you possibly be trying to learn about the Winner of the 2021 Coney Island Comedy Festival? Dan Wickes aka Master Shake aka The Wickster Scale has dedicated the past ten years of his life to roast battling for better or worse. He came in third in RBL season 3 and has battled at all the big things. He’s done Roastmasters. He’s done the old Roast Battle NYC at New York Comedy Club. He’s battled at the Comedy Cellar and Comedy Mothership. He’s battled at both the Belly Room and Main Room at the Comedy Store. He battled at SXSW. He runs the RBL NY show with an iron fist and instills fear into the battlers from his judges chair. Just kidding we’re all having fun :)', TRUE, TRUE, 3, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1789663521682-dan-wickes.webp', 'za2nHt1bzRQ0xgVRbCg2') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
