INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('gv2pj2yep', 'Porkchop', 'Male', 'Black', 1000, 'porkchopsofunny', 'PorkChop is a stand-up comedian from Hardeeville, South Carolina, known for high-energy storytelling, unpredictable punchlines, and Southern charm with just enough chaos to keep everybody nervous. With eight years in comedy, he’s performed with Don’t Tell Comedy and at festivals including Cleveland, Boston, Crooked Mouth, Fountain City, Good Karma, Rubber City, and Chateau. PorkChop turns family dysfunction, questionable decisions, and everyday chaos into the kind of laughs that make you wonder, “Should I be laughing at this?” Yes. Yes, you should.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1781921370844-Porkchop.webp', '34R1xSji5u4ZORWkNetI') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
