INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('n3jjyuhn1', 'Gina M.', '', '', 1000, 'ginamcomedy', 'Gina M is a Florida-based stand-up comedian known for her dark humor, fearless honesty, and razor-sharp wit. With an unapologetic style and bold perspective, Gina delivers laughs that are as unexpected as they are unforgettable.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1783478899066-Gina-M..webp', '656eopzhh') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
