INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('nhv8b86g5', 'Max Sorich', 'Male', 'White', 1000, 'max_sorich', 'Max Sorich is a comedian based out of Chicago. You can catch him performing at venues all over the Midwest. When not performing, Max can be found at a coffee shop looking at his phone instead of his book.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1783219487923-Max-Sorich.webp', 'flb6n9upv') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('f0cw83usd', 'Chemel', '', '', 1000, 'chemelshots', 'Chemel is a Florida-based stand-up comedian known for his quick wit, energetic stage presence, and sharp crowd work. Blending clever observations with a playful, high-energy style, Chemel delivers a fun, engaging performance that keeps audiences laughing from start to finish.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1783479057550-Chemel.webp', '656eopzhh') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
