INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('nhewti8ks', 'Spencer Devine', 'Male', 'White', 1000, 'spencertdevine', 'Spencer Devine is the Bay Area''s worst kept secret, this silly boy is a Bay Area Comedy Institution performing at the San Francisco Punchline, Cobbs Comedy Club, as well as in the various shitholes of middle California', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1784998652219-Spencer-Devine.webp', '09InnJPXmHTHc6UjLN4j') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('qis5ty6pz', 'Josh Bethania', 'Male', 'Indian', 1000, 'joshuabethania_comedy', 'Joshua Bethania is a comedian from India who''s been on the scene since 2021. Having lived in London since 2019 his comedy tends to include his observations of life in London as an outsider and what he is doing to become an insider. A few highlights in his comedy career include winning So You Think You’re Funny? 2022, winning King Gong at the Comedy Store London, Finalist at NATYs 2022, Finalist at BBC New Comedian Awards 2022 and was nominated for best newcomer in the Chortle comedy awards 2023', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1784350324831-Josh-Bethania.webp', 'P2ONL89ZfvaLZ1Ged5hC') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
