INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('zmTysSRchJdOn9pQGjTV', 'Marty Cunnie', 'Male', 'White', 1000, 'martycunniecomedy', 'Born and raised in the San Francisco Bay Area but based in Brooklyn, Marty Cunnie grew up with a large Irish Italian family, which meant trading insults with uncles, aunts, and cousins on a regular basis since he could speak. The results of years of this brutal training resulted in a comedian with a love for raucous, bawdy humor who brings energy to every crowd he performs for, whether it be on OnlyFans TV, the Punch Line, or Skankfest.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1780931026546-Marty-Cunnie.webp', 'za2nHt1bzRQ0xgVRbCg2') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
