INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('zq85pi74w', 'Sean Corcoran', 'Male', 'White', 1000, 'seany.c_', 'Sean Corcoran is a comedian and writer from Sydney, Australia. After getting his start in improv, he developed a theatrical, high-energy style that blends sharp observations with self-deprecating stand-up. Shortlisted for Best in Comedy for his debut Sydney Fringe show, Sean is the creator of The Pink Verandah - Australia''s queer answer to The Onion - and the creator and host of The Big Gay Quiz, an interactive comedy game show that grew from a Sydney event into an Australian tour in 2026.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1783015795449-Sean-Corcoran.webp', 'taf984j41') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
