INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('rwk8qi3ln', 'Liam Blackwell', '', '', 1000, '@liambcomedy', '', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1789835506594-liam-blackwell.webp', 'P2ONL89ZfvaLZ1Ged5hC') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('pqla2gxa2', 'Calw', 'Male', 'White', 1000, 'calwwalker', 'He''s gay, he''s proud, he''s loud — Calw is an unapologetic comedian who shares all of his adventures on stage... we''re excited to see what he can do in Roast Battle!', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1790245341142-calw.webp', 'NIeTzbnILTHvU69T33i3') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('wsr68hhcd', 'Chadd Lennon', 'Male', 'White', 1000, 'chaddlennon', 'Chadd Lennon is a stand up comedian, drummer in a punk band, skateboarder and life long humanitarian. And all of that at 5 foot 6 inches tall. Alright he''s not a humanitarian he just wanted to seem like a good person. Chadd didn’t consider being a roast comic when he started stand up in late 2022, but once he heard he could be mean to strangers without getting swatted or stuffed into a tiny office wastebasket, he thought to himself, “well it can’t pay any less than regular comedy” boy was he wrong. But he learned that being mean is really fun and even more fun when a large group points and laughs in agreement. With that said I don’t think a “life time ban” is in order for following that man and screaming “Dance bitch, Dance”, he really did look like Ellen Degeneres and I had had a lot of milk that day. Uh oh, I may have sent my roast bio to Barnes & Nobles “appeal your ban” email address by accident. Well anyway here’s a photo of me alive.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1785772005779-chadd-lennon.webp', 'dOfXYBu8N1KovWgOiLZ5') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('4jIRYISbDEGWGdDidwqV', 'Dayton Bissett', 'Male', 'White', 1000, 'daytonbissett', '', FALSE, TRUE, 1, 1, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1778782680743-battler.webp', 'za2nHt1bzRQ0xgVRbCg2') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('qimle9hjt', 'Tim Wolfe', 'Male', 'White', 1000, 'timwolfecomedy', 'Tim has jokes for days! Or at least a little over an hour. Winner of numerous comedy competitions (and the forever champion of the now-defunct Youngstown Comedy Festival) Tim’s jokes about poorly making sandwiches are surpassed only by his jokes about poorly working the register at PetSmart. Tim has opened for Tony Hinchcliffe, almost opened for Bob Saget, and filled in on a show Bobcat Goldthwaite didn’t wanna do. Tim is currently a headlining performer on the Brewery Comedy Tour and a staple at comedy clubs within a 50 mile radius of his mom’s house.  To call Tim a dark comedy genius is an understatement, and also not representative of his entire repertoire as he is just as comfortable making cringeworthy puns as he is amongst the horrors of reality.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1783221515312-Tim-Wolfe.webp', '34R1xSji5u4ZORWkNetI') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
