INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('ekojg2xl4', 'Thabo Tshuma', 'Male', 'Black', 1000, 'thabotshuma', 'Thabo Tshuma is Zimbabwean born, who grew up in one of the most conservative places in Australia. Far from conservative, his stand up has a unique style and perspective on his life experiences that gets brought to the stage with his hilarious twists you''d never see coming. Has performed around Australia and has opened up for Randy Feltface.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1785003537277-Thabo-Tshuma.webp', 'taf984j41') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
