INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('xtdmrnz9p', 'CeeKay Brown', 'Female', 'White', 1000, 'ceekaycomedy', 'CeeKay is a Gen Z half-French half-American one liner and storytelling comic out of Barcelona Spain and Washington DC. She doesn’t roast the people she loves; she loves the people she roasts. | Tour support for Andy Huggins, Wyatt Feegrado, Tina Friml. | As seen on BRUZZ, ARTE, Boom Chicago Festival.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1783538527340-CeeKay-Brown.webp', 'AnngcYMoHFDZK7U2xDBV') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('5pm6jsdzj', 'Mark Krikorian', 'Male', 'White', 1000, 'mark_krikorian', 'Mark Krikorian is a Chicago based standup comedian known for his sharp crowd-work, self aware humor, and quick wit. He’s performed at clubs like the comedy plex, comedy bar, Lincoln lodge, and Zanies where he connects with audiences through playful observation and spontaneous interactions. With a growing presence on stage and online, Mark brings a fresh, relatable voice to the Chicago comedy scene.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1784518252560-Mike-Krikorian.webp', 'flb6n9upv') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
