INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('nlkjj8sgf', 'Billy Swift', 'Male', 'White', 1000, 'B_swiftcomedy', '', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1790353018813-billy-swift.webp', 'CmNo4c2Rjr2PKRLxPlsU') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('rkiwbcvok', 'Julian Atwater', 'Male', 'Black', 1000, 'justjulianisfine', 'Julian Atwater, 32, is a fresh faced comedian hailing from Pittsburgh Pennsylvania. A former musician who specializes in storytelling, absurd observations and roasts. While new he has credits with Don’t Tell Pittsburgh, Don’t Tell Erie, and Roast Battle Cleveland. When he’s not telling jokes he’s doing video/audio work for local talent in his area as well as being One of Three hosts for a burgeoning Heckle Mic “King of The Castle” in Pittsburgh’s Southside.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1783278928035-Julian-Atwater.webp', 'AHjyLmocgSHDrs8Bj4fd') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('pjr84s8rt', 'Soo Ra', 'Female', 'Asian', 1000, 'hoora4soora', 'Bio: Soo Ra is an unsuspecting firecracker. She was selected for NY’s Funniest & Comics to Watch showcase in the NY Comedy Festival. She has performed at other notable festivals such as JFL Moontower & Netflix is a Joke Fest. She can be heard on the Netflix is a Joke Sirius XM channel. She’s made several appearances on BuzzFeed, Fox, and ABC. She has opened on the road for comedy greats such as Jeff Ross, Donnell Rawlings & she’s currently on a theater tour with Nate Jackson. You can check out some of her work at @hoora4soora on all platforms.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1783975147518-Soo-Ra.webp', 'za2nHt1bzRQ0xgVRbCg2') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
