INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('vjqx98quy', 'Etay Kuperman', 'Male', 'White', 1000, 'etaysuperman', 'Etay''s passion lies within entertainment, comedy and writing. All throughout his undergraduate degree he worked and volunteered at Radio Western, slowly rising through the ranks to becoming the head of the sports department his last year. Apart from radio, Etay has been performing stand-up comedy since May 2019. ', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1783277692681-Etay-Kuperman.webp', 'wrgg0p3nw') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
