INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('25z91u1iu', 'Colten Buzard', 'Male', 'White', 1000, 'coltenbuzard', 'Colten an aspiring comedian and content creator. Most of the year he''s creating content from his van as I tour the country, chasing laughs and crafting stories wherever he may find them.  Colten has recently had a hand in the Steel City Cellar, Pittsburgh''s newest comedy club.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1784010910511-Colten-Buzard.webp', 'AHjyLmocgSHDrs8Bj4fd') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
