INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('2e8f83c9h', 'AJ Leidig', 'Male', 'White', 1000, 'ajleidig', 'AJ Leidig is a Chicago-based stand up comedian. AJ started making videos online during college and quickly developed a following of over 100,000 on various social media apps. Now he uses the writing and story-telling ability on stages across the country. AJ has performed at the Vic Theater in Chicago, the Comedy Store in LA, and the Comedy Mothership in Austin. He opens for John Crist, Matt McCusker, and many more, along with performing at Chicago’s very own 312 festival.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1783277791069-AJ-Leidig.webp', 'flb6n9upv') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('pwnwjh3k4', 'Dylan Davis', '', '', 1000, 'dylandaviscomedy', 'Dylan Davis is a Florida-based stand-up comedian known for his laid-back storytelling, sharp observations, and effortlessly relatable sense of humor. Whether he''s breaking down everyday frustrations or sharing stories from his own life, Dylan''s conversational style and quick wit make every set feel like you''re laughing with an old friend. He''s performed across the Southeast and continues to build a reputation as one of Florida''s rising comics.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1783644181885-Dylan-Davis.webp', '656eopzhh') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
