INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('2yh1296u2', 'Miki Janosi', 'Male', 'White', 1000, 'mikijanosi', 'Miki is an Austin comic by way of Copley, OH.  He won the Best of Fest at the 2023 Rubber City Comedy festival and began his stand-up career in 2017 at Akron’s Funny Stop Comedy Club. Known for his sharp observational wit, candid riffs on family life, and unapologetic stage energy, Miki has performed across top Midwest showcases and underground comedy rooms.  Miki''s latest credits include Big Joke Book Winner on Kill Tony and 2026 Cleveland Comedy Festival Headliner.  He is bald for hairline reasons, don''t let his racist energy fool you.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1783278124529-Miki-Janosi.webp', 'CmNo4c2Rjr2PKRLxPlsU') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
