INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('whlqwagyv', 'Olivia Witt', 'Female', 'White', 1000, '', '', FALSE, FALSE, 0, 1, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1783277832055-Olivia-Witt.webp', 'za2nHt1bzRQ0xgVRbCg2') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('cirqv1czd', 'Tall Mike', '', '', 1000, 'tall_mike_comedy', 'Tall Mike is a Florida-based stand-up comedian whose larger-than-life presence is matched only by his sharp, high-energy comedy. Mixing quick punchlines, personal stories, and plenty of crowd interaction, Tall Mike turns everyday experiences into unforgettable laughs. Whether he''s performing in clubs, showcases, or festivals, he''s a comic who knows how to keep audiences laughing from start to finish.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1783644874967-Tall-Mike.webp', '656eopzhh') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
