INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('kf777lw3z', 'Tre Pack', 'Male', 'White', 1000, 'trepackcomedy', 'A big guy with a big personality, Tre Pack brings high-energy, relatable comedy that feels instantly familiar. A featured comic on Kill Tony and the Roast Battle League, his sets leave the room feeling less like a show and more like time spent with an old friend.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1780697818462-Tre-Pack.webp', 'U2RNyWIYAZ0DPc94EbQ1') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('AptSUiUlt00pG0KjKQzd', 'Mike Eaton', 'Male', 'White', 1000, 'mikeiseaton', 'Mike Eaton is an evil clown that somehow continues to get away with saying heinous things to his opponents. When he’s not roasting, he is eating. Those are the only two things he does. Once he figures out how to do them at the same time, may God have mercy on our souls. ', TRUE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1779308270605-battler.webp', 'CmNo4c2Rjr2PKRLxPlsU') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('6pc8lbsvj', 'Tom Crescenzo', 'Male', 'White', 1000, 'tom.crescenzo', 'Tom is from Long Island, so you can trust that he doesn’t read his jokes on stage because he most likely can’t read. He’s the poster child for extended adolescence through generational wealth, but he’s still a worthy opponent even in spite of a chronic sweating issue.', FALSE, TRUE, 1, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1781496461751-Tom-Crescenzo.webp', 'za2nHt1bzRQ0xgVRbCg2') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
