INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('86aq1bwn6', 'Preston Canavan', '', '', 1000, 'prestoncanavan', 'Preston Canavan is an active stand-up comedian, content creator, and producer based in the Orlando, Florida area. A graduate of Full Sail University, he is a frequent performer on the Florida comedy circuit, known for his unique comedic voice as an autistic American, playing five instruments, and his past experience as a blacksmith.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1783645032315-Preston-Canavan.webp', '656eopzhh') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
