INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('dl73097rm', 'Simon Bloch', 'Male', 'White', 1000, 'simonjupiter', 'Simon Bloch is a comedian and actor from NYC so he''s been humiliating himself on these city streets since before Bin Laden got his shine. He''s a pathetic little nothingburger--emphasis on the "nothing" and the "burg" because he''s Jewish. He hosts a late-night talk show called The Nighttime Routine and your nighttime routine should be slapping him around and maybe even beating him up when you see him because he''s a chode. Thanks and you''re ugly :)', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1785994557962-simon-bloch.webp', 'za2nHt1bzRQ0xgVRbCg2') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
