INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('cxgiaohqn', 'Samantha Bednarz', 'Female', 'White', 1000, 'samanthasjbednarz', 'A native New Yorker, Samantha Bednarz is a deeply personal storyteller, with a penchant for aggression. Her style could be described as controlled chaos. She spent more than a decade as a part of the NYC Comedy Scene before moving to New Orleans in December of 2021, where she quickly became a part of the local comedy scene.
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('9hwmbtp1c', 'Logan O''Brien', 'Male', 'White', 1000, 'logieobie', 'Logan O’Brien is a Boston based comedian who went to film school and also plays in a band; because the only thing he hates more than money is making his mother proud. His brand of comedy mixes judgy observations and his own personal experiences (which are highly judgeable). He’s performed in many comedy festivals, including the Boston Comedy Festival, where he was a finalist in 2025. He’s also opened for countless popular comedians including Stavros Halkias, Jordan Jensen, and Geoffrey Asmus. When he’s not on stage, you can hear him on the South Shore Boys podcast, or see him as one of the oldest guys in the crowd at a concert.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1785805440944-logan-obrien.webp', '3c0lqu31y') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
