INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('7h0695zt0', 'Adam Schroeder', 'Male', 'White', 1000, 'adamhschroeder', 'Adam Schroeder is a fast-rising comedian originally from Youngstown, OH. He is known for speaking openly on personal topics that demand the attention of any audience, while misdirects make it hard to tell where reality ended and the joke began. His act has landed him opportunities to perform in clubs, bars, and show rooms all over the east coast, mid-west, and Canada, opening and featuring for the likes of Ian Fidance, Rocky Laporte, Landon Talks, Michael Loftus, Kerryn Feehan, and many other talented comedians. He is a regular host/feature at the Pittsburgh Improv and Funny Farm Comedy Club, has performed for multiple Don’t Tell Comedy and Next Stop Comedy shows.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1783278152299-Adam-Schroeder.webp', 'AHjyLmocgSHDrs8Bj4fd') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('ca5z6i06l', 'Antoine P.', '', '', 1000, 'antoine228', 'Preston Canavan is an active stand-up comedian, content creator, and producer based in the Orlando, Florida area. A graduate of Full Sail University, he is a frequent performer on the Florida comedy circuit, known for his unique comedic voice as an autistic American, playing five instruments, and his past experience as a blacksmith.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1783645561248-Antoine-P..webp', '656eopzhh') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('eb0s5d0z6', 'Chevy Terrill', 'Male', 'Black', 1000, 'chevyterrillcomedy', 'Big Chevy Terrill has been performing stand up comedy in Akron and LA for over 20 years.  He has cerebral palsy and a history of dealing drugs.  Audiences can''t get enough of his stories about life on the streets.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1783736209386-Chevy-Terrill.webp', '34R1xSji5u4ZORWkNetI') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
