INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('b6v7wkzu5', 'Brock White Lyons', 'Male', 'White', 1000, 'whitelyonscomedy', 'Brock White-Lyons proudly represents the North Side of Lafayette, La. His edgy humor pushes the boundary of what we are allowed to laugh at. He recently opened for Arielle Isaac Norman and performs on showcases in Lafayette, Baton Rouge, Lake Charles and Austin, Tx. He’s new to comedy but a legend of the streets known by many names, Assassin Midnight, The Four Five King, The Angry Samurai. You don’t know him yet, but one things for sure, once you see him perform you’ll never forget the name Brock White-Lyons.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1783924457874-Brock-White-Lyons.webp', 'kirz803kr') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('7aeh67j2z', 'John Bennett', 'Male', 'White', 1000, 'big_throws', 'John Bennett is a NYC Comic and Lawyer from Connecticut who discovered roast battles were a good loophole to be terrible to people with little to no repercussions. Co-Founder and Co-Producer of the show @TightPantsComedy in clubs all over The Northeast (aka God’s Country).', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1786915178761-john-bennett.webp', 'za2nHt1bzRQ0xgVRbCg2') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
