INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('rbn8p5m6l', 'Mike Honore', 'Male', 'Black', 1000, 'mike_honore', 'Born and raised in Baton Rouge, Louisiana, Mike Honore is a veteran comedian who''s been performing for over 15 years. He''s done numerous shows around the country in cities such as New Orleans, Atlanta, Denver, and Las Vegas. He has been a featured performer at the Memphis Comedy Festival, Tower City Comedy Festival, and Altercation Fest in Austin. He''s opened for Eddie Pepitone, Shane Torres, Joe Derosa, Kevin Farley, and other notable touring comics. He''s also a member is the Family Dinner Improv Troupe, who''s been doing improv and movie spoofs for many years. His debut album, Splenda Afternoon, is available on all streaming platforms.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1784341838710-Mike-Honore.webp', 'kirz803kr') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
