INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('sta9dt0rn', 'Chris Scriva', 'Male', 'White', 1000, 'chrisgotreported', 'Born to a blue-collar family in the Steel City, Chris’s earliest memories take place in his father’s repair shop. He’s a former altar boy, grandma’s boy, and oldest of 3 who was raised in a mixture of Italian and Eastern European traditions. A natural non-conformist, Chris was drawn to fast cars, fast music, and the rebelliousness of stand-up at a young age and was heavily influenced by countless nights of sneakily watching Chappelle’s Show and South Park. After spending years in Chicago studying at the world’s top improvisation and sketch institutions, Chris has returned to the hilly, rusting, industrial landscape that forged him. Once a mechanical engineer, Chris now travels the world performing his own unique brand of anecdotal stand-up comedy. From Pittsburgh to Amsterdam, Los Angeles to New York, there is no place that he won’t take the stage. Check him out on YouTube at @ChrisScrivaComedy or his website www.ihatestandup.com.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1780551108130-Chris-Scriva.webp', 'AHjyLmocgSHDrs8Bj4fd') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
