INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('ys1rgc6an', 'Austin Kleeman', '', '', 1000, 'austin.kleeman', 'Austin Kleeman is a Florida-based stand-up comedian known for his sharp observations, self-deprecating humor, and easygoing stage presence. With a mix of clever writing and relatable storytelling, Austin delivers laughs that connect with audiences of all kinds. Whether he''s performing in clubs, showcases, or independent comedy rooms, he brings a polished set and a laid-back style that keeps crowds laughing.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1783645870163-Austin-Kleenman.webp', '656eopzhh') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
