INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('u0h66as0j', 'Kevin Little', 'Male', 'White', 1000, 'therealkevinlittle', 'One of the best comics out of New Orleans, Kevin Little became popular on TikTok, Instagram, Facebook, and YouTube after the pandemic. With almost a decade of experience under his belt (as of 2024) Kevin Little delivers comedic takes on a wide variety of subjects. Seriously, from popular culture to cauliflower, Kevin''s absurd take on things will leave you in stitches and provoke thought. With about 175k followers across platforms and 10''s of millions of views under his belt, this comedian can bring the laughs. From comedy clubs to festivals to even volunteering at a local rehab (Nola Detox), Kevin consistently delivers a phenomenal show.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1780500363557-Kevin-Little.webp', 'kirz803kr') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
