INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('lacecggsn', 'Silvia De Anda', 'Female', 'Hispanic', 1000, 'silviadeanda17', 'Silvia De Anda is an LA based comic; she can be seen performing at all major clubs in Southern California such as The Comedy store, The Hollywood Improv, The Laugh Factory and more. Having opened for comics such DoKnow, Concrete, Laurie Kilmartin, Shapel Lacey, and Melissa Vilaseñor, De Anda is a host at Chatterbox Comedy nights, champion of the U5 Roast Battle tournament at The Comedy Store. De Anda was a participant in the 2026 Netflix is a Joke Fest and she’s a cohost of the Dumb Tired Podcast.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1786489484659-silvia-de-anda.webp', 'EzOfMEwWjCcQ7OF6lHb9') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('ko7ollmsj', 'Matt Sullivan', 'Male', 'White', 1000, 'mattsullivancomedy', 'Matt Sullivan was the 2025 Chicago Roast Battle champion.  He has continued impressing audiences across Chicago with his joke writing skills, winning other competitions along the way.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1789092105729-matt-sullivan.webp', 'flb6n9upv') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
