INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('m3accv4qc', 'Alex MacLeod', 'Female', 'White', 1000, 'alexmacleodstuff', 'Self-deprecating, off-putting, and right-handed, Alex MacLeod performs stand-up comedy all over the world of Northeast Ohio. New to the big city and rising fast in the indie scene, she enjoys writing jokes and being roasted on progressively larger stages. ', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1781451919544-Alex-MacLeod.webp', 'za2nHt1bzRQ0xgVRbCg2') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('jWmOfidpIrAJWyV7cbPg', 'Brad Rickert', 'Male', 'White', 1000, 'bradaintfunny', 'Brad Rickert is a New York City comedian originally from a trailer park outside Gary, Indiana, which is the kind of sentence that usually ends with “your honor.” After spending ten years doing stand-up and improv in Chicago and training at The Second City, he moved to NYC where he could finally be openly gay and get his steps in.
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('9qqji0vdk', 'Pope', 'Male', 'Black', 1000, 'pope_sc', 'Pope is originally from NYC, and owns My Cuzin Vintage in Cleveland''s Gordon Square neighborhood.  He is a two time RBL Cleveland Champion and the host of the shows at the Happy Dog.  Pope won a Cleveland Comedy Award for Best Host.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1780071420201-battler.webp', '34R1xSji5u4ZORWkNetI') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
