INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('cu7rn8638', 'Brian Moses', 'Male', 'Black', 1000, 'brianmotherfuckinmoses', 'Brian Moses is the evil genius behind Roast Battle League, the comedy bloodsport that started in the Belly Room of The Comedy Store back in 2013 and never looked back. What began as a wild idea has grown into a global phenomenon, turning vicious insults into high art and launching a thousand careers (or ending them just as fast).
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('18km29ll3', 'Matt Bowman', 'Male', 'White', 1000, 'mattbowmancomedy', 'Matt Bowman is a comedian who drinks the blood of his opponents. While some might say this figuratively, Matt has the cojones to mean it literally. If you challenge him to a roast and lose, he will insist he collect what is due to him. He will roast you on stage and toast with your blood off it. He also enjoys Joe’s pizza.', FALSE, TRUE, 1, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1781496095179-Matt-Bowman.webp', 'za2nHt1bzRQ0xgVRbCg2') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
