INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('kfxfxlif6', 'Will Kristiansen', 'Male', 'White', 1000, 'futurepodcast', 'Will Kristiansen is a stand-up comedian from Toronto, ON. He has two legs and a head on top. Will has been performing all over Canada and the USA for the past ten years, and has recently seen incredible success by being mean to women and incels on stage in various basements across the continent. Will has been featured on Just for Laughs, RBL Fest Sacramento, and is a regular performer at YukYuks Toronto.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1780088792323-Will-Kristiansen.webp', 'wrgg0p3nw') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
