INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('mok9ghwnx', 'Alisha Dhillon', 'Female', 'Indian', 1000, 'alishadhillon', 'Alisha Dhillon is a Bay Area based comedian known for her candid, fearless approach to sensitive topics. She is currently the reigning San Francisco Roast Battle Champion. In 2025, she was a finalist in the San Francisco Comedy Competition and placed 2nd in the Rooster T Feather’s Comedy Competition. She has been featured in Just For Laughs Northwest, San Francisco Sketchfest, and the Edinburgh Fringe Festival.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1780500279804-Alisha-Dhillon.webp', '09InnJPXmHTHc6UjLN4j') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('0bypfsckg', 'Tommy Lynch', 'Male', 'White', 1000, 'tombonejones', 'Tommy Lynch is an American writer, humorist, and essayist.  He has been praised as the “greatest humorist the United States has produced”, with William Faulkner calling him “the father of American literature”.', FALSE, TRUE, 1, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1781650051675-Tommy-Lynch.webp', 'za2nHt1bzRQ0xgVRbCg2') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
