INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('4dmqpzlsa', 'Joseph Carter', 'Male', 'Hispanic', 1000, 'josephcartercomedy', 'Joseph Carter is an active stand-up comedian and prominent competitive roaster best known for his performances in the Roast Battle League. He Frequently performs cross-country, splitting high-profile sets between legendary venues such as The Comedy Store in Los Angeles, The Comedy Mothership in Austin, and the Comedy Cellar in New York City. He is heavily involved in the roast community, frequently engaging in head-to-head battles against other prominent roasters like Matt Bellak and Da Herm. He combines a rapid fire off the cuff style with the premeditated written style to create a hybrid ready-to-roast style that is not only entertaining, but also focuses on rhythm & fluidity.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1780499662589-Joseph-Carter.webp', 'EzOfMEwWjCcQ7OF6lHb9') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
