INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('fLk8yxyg2Xc0ScvPxwZM', 'Priya Blunts', 'Female', 'Indian', 1000, 'priyablunts', 'Priya Blunts is a stand-up comedian, actor, and producer from Queens, NY AND SHE IS OUTSIDE. When she’s not defending her life choices to her family, she’s performing across the country and collecting roast battle wins from New York Comedy Club, The Comedy Store and Comedy Mothership. Her advice? Stay hydrated, mind your business, and don’t let the Blunts smoke you.', TRUE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1780495329516-Priya-Blunts.webp', 'za2nHt1bzRQ0xgVRbCg2') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
