INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('1lpnw7t61', 'Jonathon Hollis', 'Male', 'Black', 1000, 'holliscomedy', 'Jonathon Hollis is an LA-based comedian, host, and voice actor from Atlanta. He is the host & producer of Good Cause Comedy and co-host/producer of Panic! at the Lab over at the Hollywood Improv. ', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1780583599810-Jonathon-Hollis.webp', 'EzOfMEwWjCcQ7OF6lHb9') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('9hztjlarr', 'Marc Jessie', 'Male', 'Black', 1000, 'marc.jessie', 'Marc Jessie is a powerhouse (or bottom depending on who you talk to) with the stage presence of a rock star and the wardrobe of a man who lost a bet at a high-end boutique. Born in The Bay Area but now resides in Phoenix, Arizona, you’ve seen him tearing it up on Roast Battle, Chocolate Sundaes and so much more. Known for his commanding delivery and undeniable swagger, Marc brings the heat every time he steps on stage!', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1780583665187-Marc-Jessie.webp', 'EsB8d3igfe3Vc6nV6VsN') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('25ygy5o06', 'Femi', 'Male', 'Black', 1000, 'f3mm_ee', 'Femi is one of the best roast battlers out ofChicago!! A ten time roast battle champion with an iconic laugh and extraordinary accent! He has a special skill for dark humor that’ll leave you felling guilty for how much you love it!', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1780498574334-Femi.webp', 'flb6n9upv') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('ivifSjeV9tC1rMpJD1Dg', 'Ish Gupta', 'Male', 'Indian', 1000, 'doofyish', 'Ish Gupta (AKA Connecticut''s Best Indian) has been roasting since he started comedy in 2017, first battling all over CT and New England and then beginning in NYC in 2023. He founded Roast Battle CT which joined the Roast Battle League in 2025. He hosts both of CT’s roast battles in Hartford and Stamford, and has also battled at the Comedy Cellar, New York Comedy Club, The Comedy Studio, and Laugh Boston. He often loses but its fine. He enjoys making pasta, Civil War history and anything related to Spider-Man.', TRUE, TRUE, 2, 5, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1779835194728-battler.webp', 'dOfXYBu8N1KovWgOiLZ5') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
