INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('bncp747s9', 'Wes Boggs', '', '', 1000, 'Wes_boggs_comedy', '', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1787054088198-wes-boggs.webp', 'm8qfn6yjl') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('9tz6s3gu0', 'Kadija Wingo', 'Female', 'Black', 1000, 'freekwingo', 'Kadijah Wingo “KWINGO,” is a force of nature in the world of comedy, acting, writing, and producing. Hailing from Cleveland, Ohio, she’s carving out her unique space in the industry, most recently hitting new heights at Cleveland Public Theatre, where she’s been behind the scenes curating cutting-edge festivals of fresh theatrical works. When she’s not turning visions into reality for other artists, she’s electrifying local stages at hotspots like Snowflake Comedy, Don’t Tell Comedy CLE, Imposters, and Con Tú, to name a few. As a featured comic at the Detroit Women of Comedy Festival and a finalist in the Bill Squires Comedy Contest, Kwingo’s talent is undeniable. Though she eats in many ways, her passion for collaboration and constant evolution as an artist drives everything she does.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1781914772712-Kadija-Wingo.webp', '34R1xSji5u4ZORWkNetI') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
