INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('xf94z6lxj', 'Shota Saimu', 'Male', 'Asian', 1000, 'shotasaimu', 'If you want to see battlers destroyed with just a "Yes" as a comeback, Shota is your guy. Performing both in English and Japanese, Shota Saimu is a name that''s quickly rising up the ranks both in Japan and abroad. Stop asking for subtitles for his battles!', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1780763255461-Shota-Saimu.webp', 'NIeTzbnILTHvU69T33i3') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
