INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('ric0sbvjd', 'Gino Christofaro', 'Male', 'White', 1000, 'gino.comedy', 'Gino is a German-Brazilian comedian and lovable asshole. After starting out with comedy in NYC, Gino moved back to Berlin and became a showrunner and booker at Ma’s Comedy Club. He regularly performs around Europe and has participated at the Comedy Central Roast Battles, the American Stand Up Tour in Switzerland, Nightwash, Comedy Studio Berlin and the Hamburg International Comedy Festival six times. 
