INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('8yb8ohl4p', 'Devansh Sharma', '', '', 1000, 'bloodyhellthebrits', 'Devansh is an expert in comparative studies, an observational comic who sees Berlin with a cynical eye. He navigates the often uncomfortable truths lurking beneath the surface of everyday life.
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('f71goa7a6', 'Fitz Gessler', '', '', 1000, 'fitz_comedian', 'Originally from New Zealand 🇳🇿 with German parents 🇩🇪 and now based in Berlin, Fitz has become a familiar face across Europe’s comedy scene, performing everywhere from small clubs to theaters. His mix of Kiwi and German gives a unique perspective rarely seen.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1780687269722-Fitz-Gessler.webp', '4w8gi6ahm') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
