INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('jbieup19j', 'Max Kevin', 'Male', 'White', 1000, 'maxkevincomedy', 'Max Kevin looks like he holds some disturbing thoughts, but he''s a very nice guy. It is disturbing to hear him speak in such a high-pitched voice though. He also has a podcast, because of course he does.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1780762621704-Max-Kevin.webp', 'NIeTzbnILTHvU69T33i3') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('4c5zcfh55', 'Doug', 'Male', 'White', 1000, 'dougpagecomedy', 'Mysterious, dark and dreamy, Doug Page is an enigma. He recently had to return back to America, but he didn''t leave the scene without a battle up his belt.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1780761126105-Doug.webp', 'NIeTzbnILTHvU69T33i3') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('epyzhzhje', 'Troy Lewis', 'Male', 'Black', 1000, 'ranchoneverythang', 'A goofy, impenetrable wall of pure muscle and vibes, there''s a reason this 2019 Shenzhen International Comedy Competition Winner held the Tokyo Champion belt and was invited to battle at The Mothership. Troy is also an Ivy League graduate, which you would never guess from watching him walk up to the SpongeBob SquarePants theme. It''s said that the opponents he destroyed all have nightmares of his "HUE HUE HUE" laugh for months.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1780835617956-Troy-Lewis.webp', 'NIeTzbnILTHvU69T33i3') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('tu7euwfal', 'Bill E Miller', 'Male', 'White', 1000, '', 'One of Tokyo''s most beloved Roast Battle comics, Bill is taking a break from the stage for now... but he''s given us so many amazing battles over the years. We miss you, Bill.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1780817536665-Bill-E-Miller.webp', 'NIeTzbnILTHvU69T33i3') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
