INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('hfrbsdhj9', 'Allen Lemus', 'Male', 'Hispanic', 1000, 'kingguate', 'Danbury, CT native Allan Lemus brings unapologetic, boundary-pushing comedy to every stage. Co-host of the Funny Fellas Podcast and runner of O’Connor’s open mic, this Guatemalan-American comic finds the funny in absolutely everything—vulgar, raw, and relentlessly hilarious.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1780700939638-Allen-Lemus.webp', 'dOfXYBu8N1KovWgOiLZ5') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('0egkmxtus', 'Jiro', 'Male', 'Asian', 1000, 'jirodidwhat', 'Jiro is the co-producer, soundboard / videographer for Tokyo — he also hops on to battle when the bar needs an Asian face on the poster.
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('5dbnl04vo', 'Jake Spencer', 'Male', 'White', 1000, '77jakes', 'Jake is actually not a Tokyo comic, he''s just listed with us on this database because RBL Vancouver exited the league after Jake came to Tokyo to battle. We are holding Jake hostage until Vancouver comes to their senses.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1780837578925-Jake-Spencer.webp', 'NIeTzbnILTHvU69T33i3') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('idpr7hro1', 'Taline', 'Female', 'Middle Eastern', 1000, '', 'We all thought Taline was just a sweet French comedian that would never do Roast Battle. Then she did her first ever battle, destroyed, and went back to France.', FALSE, TRUE, 0, 0, 0, 'https://images.squarespace-cdn.com/processed/webp/taline-red-1.webp?format=750w', 'NIeTzbnILTHvU69T33i3') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
