INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('r0268vw81', 'Jody Miller', 'Female', '', 1000, '', '', FALSE, FALSE, 0, 0, 0, '', 'EzOfMEwWjCcQ7OF6lHb9') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('7bneuia9o', 'Mike Paxman', 'Male', 'White', 1000, '', 'One of Tokyo''s ace battlers, Mike Paxman is a machine that''s mean and used to be lean. Currently on father''s leave, he''s scheduled to return on stage this year but for now he''s busy annoying everyone with photos of his newborn.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1780762846027-Mike-Paxman.webp', 'NIeTzbnILTHvU69T33i3') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('pazir326r', 'Josh Adams', 'Male', 'White', 1000, 'brujah600', '"A Capybara on his way to Jan 6" — an army vet and former cop from Florida, Josh will say shit you''d exactly expect someone of his background to say. He swears he''s not racist though.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1780730229675-Josh-Adams.webp', 'NIeTzbnILTHvU69T33i3') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('gymy2g3c4', 'Mickey Acorn', 'Male', 'White', 1000, 'for4seconds', 'One of the most coked-up looking sober person you''ll see on stage, Mickey Acorn is a high-energy octane burst that leaves you doubting reality itself. No one knows details about his past life, but we hear he was some kind of actor.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1780762699760-Mickey-Acorn.webp', 'NIeTzbnILTHvU69T33i3') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('828edqck3', 'Babush', 'Male', 'White', 1000, 'not.babush', 'As handsome as he is, Babush''s roast jokes are not nearly as sweet as his face — hailing from a small farming village in Italy, Babush has given us some amazing battles against some real heavy hitters like Yurié Collins. Babush had to leave Tokyo and went to Toronto for work, but we''re awaiting his return... he really hates Toronto, after all.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1780757146316-Babush.webp', 'NIeTzbnILTHvU69T33i3') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('jyxr5117d', 'Corey "Blue Collar Corey" Heider', 'Male', 'White', 1000, 'heidercorey', 'Dude from Trash Filled Houses', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1786916179629-corey-blue-collar-corey-heider.webp', 'AHjyLmocgSHDrs8Bj4fd') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('jqz0t2xp5', 'Yurié Collins', 'Female', 'Asian', 1000, 'babypinkhaus', 'Yurié Collins is a dynamic actress, comedian, and content creator based in Tokyo. With performances at The Comedy Store, sold-out shows at the New York Comedy Festival, Yurié is marching into the US stand-up scene — but she hasn''t forgotten her Roast Battle roots! ', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1782278787926-Yuri__-Collins.webp', 'NIeTzbnILTHvU69T33i3') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('qeuztcitg', 'Akari', 'Female', 'Asian', 1000, 'akari_cleansmartcomic', 'Don''t be fooled by her cute looks, Akari is an absolute heavy hitter in Roast Battle. Beneath her massive forehead is a big brain that is constantly looking for a painful way to roast her opponent.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1780790578510-Akari.webp', 'NIeTzbnILTHvU69T33i3') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('t3a8rl921', 'Isaac Knox', '', '', 1000, '', '', FALSE, TRUE, 0, 0, 0, '', 'za2nHt1bzRQ0xgVRbCg2') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('bhzjrpp1h', 'Piña', 'Male', 'Hispanic', 1000, 'pina.presents', 'Piña has already heard all your fat and Mexican jokes, mostly from his dad. A translator and writer by trade, Piña is just looking for a way to pay his bills. Seriously, someone please help him so he doesn''t get sent back to Texas.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1782278942179-Pi__a.webp', 'NIeTzbnILTHvU69T33i3') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('fx2ixxr7t', 'Kat Randle', 'Female', 'White', 1000, 'katrandle', 'You may not know Kat Randle, but you will know that she''s bisexual because it''s going to be the very first thing she''ll remind you in a conversation. A staple figure in the Tokyo standup scene, Kat is an amazing writer and performer in Roast Battle also. Did I say that she''s bi?', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1780820339937-Kat-Randle.webp', 'NIeTzbnILTHvU69T33i3') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('pwlijuhkl', 'Adi', 'Male', 'Indian', 1000, 'aditya.durbha', 'Adi is a young Indian man living in Tokyo. Of course he works in IT. While he''s still early into his stand-up career, Adi has already opened for international comedians such as Nitinn R Miranni, and is working to create impact in Roast Battle as well. Just don''t let him rap on stage ever again.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1780742012101-Adi.webp', 'NIeTzbnILTHvU69T33i3') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('4behvmswu', 'Yo', 'Female', 'Asian', 1000, 'yoyoyo_comedy', 'As a trilingual comedic force, Yo has performed standup comedy in her native Chinese tongue, English, and Japanese on stages across Asia. Off-stage she''s usually a calm and resolved corporate slave, but in Roast Battle... I mean, have you ever witnessed two Chinese people arguing with each other?', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1780836423507-Yo.webp', 'NIeTzbnILTHvU69T33i3') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
