INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('jw6x4xqb8', 'Patrick Eaton', '', '', 1000, 'Comicpateaton', '', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1787054211733-patrick-eaton.webp', 'm8qfn6yjl') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('tguui0ld5', 'Evans Musoka', 'Male', 'Black', 1000, 'evans_musoka', 'Originally from Kenya, Evans is a staple name in the Asian comedy scene, having performed in multiple countries from the Middle East to the Pacific in his 10+-year-career. He''s usually seen spitting fire from the judging table, but will sometime spring on stage to take matters into his own hands.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1780818560077-Evans-Musoka.webp', 'NIeTzbnILTHvU69T33i3') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('7bt86fikb', 'Kat Rowan', 'Female', 'White', 1000, 'thekatplanet', '"Surprisingly straight" — Kat Rowan a.k.a. "the other Kat" is a comedian, musician, and staff member of Tokyo Comedy Bar, Japan''s only standup comedy club. Recently she''s been trying to reclaim her Scottish heritage by trying to be a Celtic FC fan. Up the hoops?', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1780762405459-Kat-Rowan.webp', 'NIeTzbnILTHvU69T33i3') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('gkohwkue8', 'Shoin Wolfe', 'Male', 'Asian', 1000, 'shoinwolfe', 'Handsome, successful and in a happy marriage, what is there to roast about Shoin? Unrelated but he never takes off that cap of his. Hmm. Shoin might appear charming and harmless, but he can say some real hurtful stuff.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1780764802170-Shoin-Wolfe.webp', 'NIeTzbnILTHvU69T33i3') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('x8irnq42l', 'Michael K', 'Male', 'White', 1000, 'keferl', 'After suffering a failure in his business venture, Michael K went up on stage and has been rampaging through the Tokyo comedy scene. Having opened for Jiaoying Summers, he was also part of the Monsters of Tokyo that toured across the US, appearing at premier comedy clubs including The Comedy Store, Hollywood Improv, Cobb''s Comedy Club, Helium Comedy Club, and Cap City Comedy Club. No one knows what the K stands for and we''re afraid to ask at this point.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1780760767171-Michael-K.webp', 'NIeTzbnILTHvU69T33i3') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('hc118owll', 'Elyssa Penson', 'Female', 'White', 1000, 'elyssa_penson', '', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1784776964409-Elyssa-Penson.webp', '3c0lqu31y') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
