INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('tjprwzm6j', 'Joe Lowers', 'Male', 'White', 1000, 'joelowers', 'Nationally Touring Comedian and Founder of The World Series of Comedy', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1786916325614-joe-lowers.webp', 'AHjyLmocgSHDrs8Bj4fd') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('r2ihq97ee', 'Lino Rodriguez', 'undecided', 'undecided', 1000, '', '', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1781401783941-Lino-Rodriguez.webp', 'CmNo4c2Rjr2PKRLxPlsU') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('98ea1vxnl', 'Dylan Lamb', 'Male', 'White', 1000, 'dylanlamby', 'Dylan is an Australian comedian based in Osaka, Japan. As a co-founder of Kansai Comedy, Dylan has been spreading stand-up at the home of Japanese manzai comedy. From time to time, he visits Tokyo to roast those snobby Tokyoites.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1780761170426-Dylan-Lamb.webp', 'NIeTzbnILTHvU69T33i3') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('fumbi6h3k', 'Maiya Kinoshita', 'Female', 'Asian', 1000, 'maiyakcomedy', 'Maiya has survived working in what is famously one of the worst working environments in Japan, she''s a tough nut to crack in Roast Battle. Performing in both English and Japanese, she releases all the frustration she has from dealing with her Japanese bosses on her opponents. One of her key moments in Roast is definitely battling 4-time AVN MILF of the Year Award winner Alexis Fawx.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1780762462307-Maiya-Kinoshita.webp', 'NIeTzbnILTHvU69T33i3') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('bauqw5t3n', 'JJ Wakrat', 'Male', 'White', 1000, 'jjwakrat', 'As the founder and producer, booker of Roast Battle Tokyo, JJ is the pillar that holds the Tokyo scene together (and is shaped like one).
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('j7u15wizk', 'Jon Sabay', 'Male', 'Asian', 1000, 'worst_finest', '[8 PM] Jon shows up saying “I’ve got nothing”. [8:15 PM] Jon screams “I HATE ROAST BATTLE” to a poor salaryman. [8:30 PM] Jon calls his therapist. [8:45 PM] Jon recedes into fetal position. [9:00 PM] Show starts. Jon shrieks. [10:30 PM] Jon crushes his headlining battle. — Comedian, screen/stage actor, improv coach, showrunner, Jon Sabay has as much talent as he has daddy issues. A veteran in the Asian comedy scene, Jon is also an avid Street Fighter fan and DnD DM. ', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1780819183035-Jon-Sabay.webp', 'NIeTzbnILTHvU69T33i3') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('fju3o49qw', 'Ruby Rosales', 'Female', 'Hispanic', 1000, 'ruby_rosales_comedy', 'Bringing her Latina sass to the land of the rising sun, Ruby performs comedy in both English and Spanish in Tokyo (yes there''s a big Spanish-speaking community!). Also her dad is very scary.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1780763176129-Ruby-Rosales.webp', 'NIeTzbnILTHvU69T33i3') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
