INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('rw88ri3xv', 'Chris Harrison', 'Male', 'White', 1000, '', 'A big brute with an even bigger heart, Chris Harrison is NOT the bouncer at Tokyo Comedy Bar. He''s also extremely fluent in Japanese — in Japanese he talks like a 20-year-old college kid you see drunk in Takadanobaba.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1780837104957-Chris-Harrison.webp', 'NIeTzbnILTHvU69T33i3') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('qro6aosmk', 'Josh Levy', 'Male', 'White', 1000, '', '', FALSE, TRUE, 0, 0, 0, '', 'za2nHt1bzRQ0xgVRbCg2') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('3z6tn8cyw', 'Chris Natsuume', 'Male', 'White', 1000, 'chrisnatsuume', 'Chris Natsuume (Mr. Summerplum in Japanese) brings unfiltered Texan suburban dad energy onto the stage. Chris''s comedy accomplishments include going viral after triggering weebs from his Japan rant. People keep referring to him as their "comedy daddy", and we don''t want to know why.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1780741839538-Chris-Natsuume.webp', 'NIeTzbnILTHvU69T33i3') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('HEkJGwwgJnFprVtbCykB', 'Malia Simon', 'Female', 'White', 1000, 'maliasimon', 'Malia is a comic, writer, and battler who has been in the running for New York''s MVP. Malia has been seen at the NY Underground Comedy Festival, the Edinburgh Fringe Festival, and Time Out NY. Malia writes satire for Reductress and The Hard Times. ', TRUE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1779519896373-battler.webp', 'za2nHt1bzRQ0xgVRbCg2') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
