INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('fxdu16zo7', 'Sam B', 'Male', 'White', 1000, ' theonlyrealsamb', 'If there''s a Sam B, is there a Sam A? Inquiring minds would like to know. Sam didn''t just come to Japan for the anime, he also speaks business-level Japanese and performs in Japanese as well. As the bar manager at Tokyo Comedy Bar, he sometimes battles on stage, but he''s usually battling alcohol addiction.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1780764757794-Sam-B.webp', 'NIeTzbnILTHvU69T33i3') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
