INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('3v4785oqf', 'Carter Dahlgren', 'Male', 'White', 1000, 'carterd_tv', '', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1784773854856-Carter-Dahlgren.webp', 'm8qfn6yjl') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('8hltu7xh9', 'Yasushi', 'Male', 'Asian', 1000, 'yasushiuechi', 'As a Korean-Japanese, the two halves of Yasushi already hate each other viciously — he''s no stranger to being mean and funny on stage. Yasushi actually didn''t speak a lick of English before doing standup and learned it through performing. It''s nice to see this art form actually benefit society sometimes.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1780765112156-Yasushi.webp', 'NIeTzbnILTHvU69T33i3') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('bz4la0knp', 'Drew', 'Male', 'White', 1000, '', 'A boxer, rugby player and snowboarder, before he returned to the US Drew was one of the rare fit comedians in Tokyo. Or in the world.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1780765054346-Drew.webp', 'NIeTzbnILTHvU69T33i3') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('jUHAs6kiRTsHKPafKOwo', 'Andrew Manning', 'Male', 'White', 1000, 'andrewmanthing', '“Andrew Manning had a spinal tap when he was 29 days old because he didn’t reach the 30 day mark.  If he had gone 30 days, they wouldn''t have needed to spinal tap him.  He had a fever.  This was at a teaching hospital, so they were pretty aggressive with him.  So that was his welcome into society, ha ha.”
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('HYaRzhZ74y1hCmF2ywtN', 'Irina Chelidze', 'Female', 'White', 1000, 'irinacdze', 'Irina Chelidze is a famous actress who has won multiple awards. She was born in the country of Georgia and raised in Brooklyn, where she was taught most of the cuss words she uses to this day. She speaks 4 languages, loves to cook, sing, and hunt lantern flies. You can usually find her arguing with wait staff on behalf of her fiancee, famous Roast Comic Joshua Lampley. ', TRUE, TRUE, 2, 1, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1778783456840-battler.webp', 'za2nHt1bzRQ0xgVRbCg2') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('lcdq2ysoq', 'Mark Darden', 'Male', 'White', 1000, 'markdardencomedy', 'Mark Darden is a stand up comic and comic book writer from Indiana.  He looks old enough to know better.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1781916214574-Mark-Darden.webp', 'm8qfn6yjl') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
