INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('ex8B507HvJOSiAgIg59s', 'Joe Mac', 'Male', 'White', 1000, 'moreonjoemac', 'Joe Mac is the guy you cheated off of in school. Born and raised in Queens, roasting was part of his life early and often. He''s a veteran roaster with a lot to prove, still looking for new ways to insult his opponents. When he''s not competing in Roast Battle, he''s mistaken for Steve from Blues Clues and getting offers for children''s birthday parties.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1781654263413-Joe-Mac.webp', 'za2nHt1bzRQ0xgVRbCg2') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('t6xqiz8zk', 'Hudson Torres', 'Male', 'Hispanic', 1000, 'hudson_torres.c', 'Hudson Torres is an 18 yo comic and roaster from New York City. He made his stand up debut at 16, and his roast debut at 17 going 4-0 with the judges. He knows his youth lets him say what he wants, but he goes for clever roasts instead of just being offensive.  Performing all over NY and LA has given him an edge, which combined with his age affords him a presence unlike anyone else. Unlike him this bio is short and sweet.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1780938181317-Hudson-Torres.webp', 'za2nHt1bzRQ0xgVRbCg2') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('7r4uuw8w2', 'J.D. Witherspoon', NULL, NULL, 1000, NULL, NULL, FALSE, TRUE, 0, 0, 0, NULL, 'EzOfMEwWjCcQ7OF6lHb9') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('cslji5dto', 'Harry Metcalf', 'Male', 'White', 1000, 'hgmetcalf', 'A former regular at Roast Battle Tokyo, Harry has currently returned to his native country of Austalalaland. While he''s taking a break from battling himself, we hear he gives (solicited) advice to new battlers entering the scene...', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1781015185523-Harry-Metcalf.webp', 'NIeTzbnILTHvU69T33i3') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
