INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('rs1odzw05', 'Esther', 'Female', 'Black', 1000, 'rehtseesther', 'Esther is a 2x Roast Battle Champion, LGBTQ+ New Comedian of The Year finalist & won Best Newcomer at the Barcelona Comedy Awards. She''s opened for Michelle Wolf and has battled at the Edinburgh Festival Fringe, the Comedy Cellar in NY and the Comedy Mothership in Austin. After starting out in Barcelona and getting tired of constantly winning (17-2), for RBL season 4, she decided to get with the winning team, hoe', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1780609706201-Esther.webp', 'P2ONL89ZfvaLZ1Ged5hC') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
