INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('UE0Nk9l9XmVwCX6dz3ZI', 'Michael Kaufman', 'Male', 'White', 1000, 'michaelkaufman824', 'As the unofficial mascot of NYC roast battle, Michael Kaufman keeps showing up to the weekly battles without anyone asking him to. Kaufman is best known as the guy who got his first and (hopefully not) only win against RBL Co-Producer Scott Hall. This comes up in many in-person conversations mostly because he and producer, Dan Wickes refuse to let Scott live it down. Scott, if you’re reading this, you’re my bitch', TRUE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1780460510869-Michael-Kaufman.webp', 'za2nHt1bzRQ0xgVRbCg2') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('pak66ivuk', 'Bek', 'Male', 'Black', 1000, 'sebekbattle', 'Bek hosts the Monday Night Wrang Open Mic at the Five O''clock Lounge every Monday.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1781905529550-Bek.webp', '34R1xSji5u4ZORWkNetI') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('pyb1pyk7v', 'Chris Clem', 'Male', 'White', 1000, 'chrisclemnet', 'Chris Clem is a 20 year veteran of stand up comedy, a level 15 improviser trained at Second City Detroit, a trained professional wrestler, a father of three girls, and the last liberal Kid Rock fanboy.  He has hosted a Cavaliers podcast and the number 1 American made podcast in South Asia, Pretty Swell Guys.  He makes fashionably late seem passe.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1781906644961-Chris-Clem.webp', '34R1xSji5u4ZORWkNetI') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
