INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('l9j3uc3d8', 'Alex Bartle', 'Male', 'White', 1000, 'alex_bartle_', 'Alex was a college student on a prestigious exchange program in Tokyo, then decided to start doing standup here. We can only assume the unfortunate events that led to that decision. He''s back in his home country of UK now, graduated and found work — we''re glad he came to his senses.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1781014425880-Alex-Bartle.webp', 'NIeTzbnILTHvU69T33i3') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('xo4igyi2k', 'Noah Brockett', 'Male', 'White', 1000, 'noah_brockett', '"Professional bumper car driver" and a blind comedian based in Charleston, North Carolina, Noah originally started performing comedy at the Tokyo Comedy Bar. Somehow every winter he manages to find his way back to Tokyo to battle.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1780762981468-Noah-Brockett.webp', 'NIeTzbnILTHvU69T33i3') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
