INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('b7by96l37', 'Younes Benslaoui', 'Male', 'Other', 1000, 'younesbenslaoui', 'Younes is a Moroccan Comedian. Born in Austria and raised in Germany while surrounded by people of many different cultural backgrounds, he learned very quickly that he doesn’t know anything in life and he doesn’t pretend to. He’s silly, stupid and proud!', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1780681814452-Younes-Benslaoui.webp', '4w8gi6ahm') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('gcujgsd9l', 'Zach Mandell', '', '', 1000, '', 'Zach Mandell has been doing standup since 2022 and competing in roast battles since 2024. He is a native of Virginia and a resident of West Hartford, CT. He often jokes about being a teacher, a jew, and a fat alcoholic." He is known for his dry wit and moist handshakes.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1780697034597-Zach-Mandell.webp', 'dOfXYBu8N1KovWgOiLZ5') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('WFFt8h3fqhN89mqPG0rI', 'Myka Fox', 'Female', 'White', 1000, 'mykafox', 'Myka Fox is a comedian, roast battler, judge, and comedy writer whose savage joke writing has made her a fixture in the roast comedy world. She has competed in and judged for Roast Battle League and Roast Masters, earning a reputation as one of the sharpest and most feared joke writers in the scene.
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('ebb3r9dst', 'Kansei Yasuda', 'Male', 'Asian', 1000, 'kanseicomedy', 'Kansei Yasuda is a Toronto-based stand-up comedian who began his career at Tokyo Comedy Bar. A recent Kill Tony Golden Ticket winner, he''s made national Canadian television and radio appearance with  international touring credits. Most recently, he toured the United States as part of the Monsters of Tokyo Tour, appearing at premier comedy clubs including The Comedy Store, Hollywood Improv, Cobb''s Comedy Club, Helium Comedy Club, and Cap City Comedy Club. It''s also said that without a daily consumption of Tondou Ramen (TM), Kansei would simply cease to exist.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1780762111295-Kansei-Yasuda.webp', 'NIeTzbnILTHvU69T33i3') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
