INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('brszestlk', 'Jan Tatlock', '', '', 1000, '', '', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1787054322432-jan-tatlock.webp', 'm8qfn6yjl') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('RfO66FKwAPgmxqagfxsO', 'Jamie Wang', 'Female', 'Asian', 1000, 'jamiewangcomedy', 'Jamie Wang is an NYC based comedian from Shanghai, China, previously based in Taiwan. She has quickly ascended as a rising star in the Asian comedy circuit.
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('11yvdpitg', 'Chris Paugh', 'Male', 'White', 1000, 'chrisepaugh', 'Chris Paugh is a father, graphic artist, comedian and firebrand from Cleveland, OH. Chris is best known as a fearless idealist grounded firmly in reality. He started his artistic exploits as a pop culture podcaster in Columbus, OH in the late 2000''s, making the transition into stand up comedy and quickly picking up a knack for producing quality shows in the area. After moving back to Cleveland with his family, Chris immediately won the Funny Stop Amateur Night contest. Audiences fell in love with his effortless attacks on conventional social, sexual and political norms. Chris recorded two well received albums, American Pothead and Apaughcalypse Now.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1779856346565-battler.webp', '34R1xSji5u4ZORWkNetI') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('mx49qz1zw', 'Avery Dauer', 'Male', 'White', 1000, 'averydauercomedy', 'Avery Dauer is a San Francisco Native LA based Stand-Up Comedian, Writer and Filmmaker currently attending Occidental College. Avery is consistently ranked as one of the top 25 battlers in the world and regularly battles and performs at the World Famous Comedy Store, outside of Roast Battle, Avery''s credits include Netflix is a Joke Festival: The Jump Off Show, Cobbs Comedy Club, SF and Sacramento Punchlines, Comedy Works Denver, Denver Comedy Underground, The Comedy Mothership as well as Yuk Yuk''s Toronto and Burlington (CAN). Avery has featured for national touring comedians such as Usama Siddique and Ahren Beslisle. Avery uses his quick wit and unique perspective to educate his audiences about the nuances of disability and systemic ableism and other retarded shit like that.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1781145612023-Avery-Dauer.webp', '09InnJPXmHTHc6UjLN4j') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('q8pwd7lda', 'Austin Shook', '', '', 1000, '', '', FALSE, TRUE, 0, 0, 0, '', '3ld5tjmcr') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('cnmawv2kc', 'John Brown', 'Male', 'White', 1000, 'johnbrowncomedy', 'John Brown brings a high-energy blend of clever observations, real-life mishaps, and just the right amount of mischief. He’s the comic who makes you laugh at the things you didn’t realize you all had in common - work, family, dating, the Midwest… nothing is safe, and everything is hilarious. His timing is tight, his crowd work is playful (and razor-smart), and he knows exactly how to turn a room into a rolling wave of laughter.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1780074902655-John-Brown.webp', '34R1xSji5u4ZORWkNetI') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('z19shf34g', 'Bryan Sternik', 'Male', 'Hispanic', 1000, 'thebryansternik', 'Bryan Sternik is a master of charming chaos. Half Puerto Rican and half Polish, his comedy pulls from the everyday mishaps, misunderstandings, and perfectly timed missteps that make life ridiculous. Whether performing in a comedy club, an amusement park, or a bowling alley, Bryan has a knack for turning relatable blunders into big laughs and unforgettable moments.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1781906461459-Bryan-Sternik.webp', '34R1xSji5u4ZORWkNetI') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('ct66k74am', 'Drew Gigis', 'Male', 'White', 1000, 'drewgigis', 'Drew Gigis is happily married in Cleveland, OH.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1781907438010-Drew-Gigis.webp', '34R1xSji5u4ZORWkNetI') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
