INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('ywwc6zgir', 'Dan Wilson', 'Male', 'Asian', 1000, 'danielywilson', 'Dan Wilson is a Japanese manzai comedian, stand-up comic and popular content creator based in Tokyo and he will TEACH YOU SOME JAPANESE! His comedy is never ASAHI SUPER DRY, a 100% guaranteed TOTTEMO WETTY experience. WAKATA WAKATA WAKATA!!!! If all you J-GNORANTS didn’t know how to say pussy fart in Japanese, you are going to POUND TOWN, YANAMSAYIN’!? YEAH YANAMASAYIN''!!!', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1780759771325-Dan-Wilson.webp', 'NIeTzbnILTHvU69T33i3') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('bdb99k5bg', 'Jamie C', 'Male', 'White', 1000, '', 'A born and bred Detroiter, Jamie has lived in Japan for most of his adult years and is a known veteran in the Tokyo scene. He loves collecting vinyl, leather jackets, and plays in an Irish band. Yeah, none of those were surprising facts. Jamie also is often part of the shooting squad at the Tokyo judging table.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1780761447138-Jamie-Cook.webp', 'NIeTzbnILTHvU69T33i3') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
