INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('id0n9s49x', 'Flem Love', 'Male', 'Black', 1000, 'flovecomedy', 'One of the local degenerate stand up comics in the Cleveland comedy scene. Flem started doing comedy in Orlando FL in 2019. Flem grew up watching stand up comedy as a kid and he''s been obsessed with it since.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1781908508940-Flem-Love.webp', '34R1xSji5u4ZORWkNetI') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('ibmlo9qct', 'Julia Mary', 'Female', 'White', 1000, 'juliaamaryyy', 'Julia is a relentless tornado of comedic anarchy and a fearless force of nature. When she’s not giving city tours on the Funny Bus in downtown Cleveland, you can find her doing local comedy shows, hanging out at home with her dog, or crying in a public bathroom. Some may describe Julia as “a bit much”, others would say she''s “way too much” - either way she’s guaranteed to make you laugh. ', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1781914472825-Julia-Mary.webp', '34R1xSji5u4ZORWkNetI') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
