INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('sqzc2wnhn', 'Ruben VM', 'Male', 'White', 1000, 'rubenverymuch', 'Tokyo''s best and only musical comedian, Ruben the Pale White Dutch is the co-producer, SFX guy and videographer for Roast Battle Tokyo. He also performs in Japanese, delivering hard-hitting criticisms of Japan from the eyes of a white hetrosexual male, such as the lack of whole wheat bread. ', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1780763087292-Ruben-VM.webp', 'NIeTzbnILTHvU69T33i3') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('lacr652lr', 'Lukas Arnold', 'Male', 'White', 1000, 'lukastarnold', 'Lukas Arnold (born 8 January c. 1982-1984) is a North Korean politician and dictator who has served as the supreme leader of North Korea since 2011, following the death of his father, Kim Jong II. He is the third ruler from the Kim family to lead the country, which was founded by his grandfather Kim Il Sung. Lukas holds the positions of general secretary of the Workers'' Party of Korea (WPK) and president of the State Affairs Commission, as well as the highest offices in the Korean People''s Army.
