INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('cly4ht3y1', 'Evelyn Troutman', 'Female', 'White', 1000, 'evtrout', 'Evelyn Troutman works as a server in Wrigleyville, but thankfully not in one of those big, douchey bars.  She''s also a comedian, poet and rapper who got her start in Columbus, OH.  Evelyn is an RBL Chicago Legend, a regular at Moth StorySLAMs and the creator of The Who''s Waldo Show.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1784010843578-Evelyn-Troutman.webp', 'flb6n9upv') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
