INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('wdih2bz3e', 'Tabitha Jones', 'Female', 'White', 1000, 'seaworldashtray', 'Tabitha proudly refers to herself as Cleveland’s Grossest Girl, yet she beats the hell out of everyone in Roast Battles.  This woman is a content generating machine, yet still has time to lead the kind of life worth discussing onstage and online.  Catch this Depressed Banshee Nightmare Queen while you can, as she is living fast, probably dying young and will leave an exquisite corpse.  Tabitha has been featured as one of Ohio’s best female comics on Cleveland.com and was 2024 and 2025’s Cleveland Scene Magazine Best Comedian (female).  She co-produces Roast Battle Cleveland and Sketch Battle at Imposters Theater.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1780081518140-Tabitha-Jones.webp', '34R1xSji5u4ZORWkNetI') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
