INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('0rs95k4po', 'Faye Fahsbender', 'Female', 'White', 1000, 'fayefazz', 'Faye is from an east side suburb outside of Cleveland and went to Kent State University.  She enjoys going to the gym, cooking, spending time with family and friends, going to the movies, and performing stand up comedy in the Cleveland area.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1781908326897-Faye-Fahsbender.webp', '34R1xSji5u4ZORWkNetI') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
