INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('bcd2xgosm', 'Joe Ferraro', 'Male', 'White', 1000, 'jomo_eco', 'Joe Ferraro is a comedian and producer in Easton, Pa. A regular on most every stage in the Lehigh Valley, Ferraro performs all over Pennsylvania and is the founder of the Easton Comedy Offensive.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1783277906445-Joe-Ferraro.webp', 'cOWxAMnJvIjbYvcO7Emd') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('eg7mdiptd', 'Kyle Haunhorst', 'Male', 'White', 1000, 'hahahauny', 'Kyle Haunhorst is a Producer, Roast Battler and Comedian from Cleveland, Ohio. He is the Co-Producer of Roast Battle Cleveland and the director of The Cleveland Comedy Festival and Rubber City Comedy Festival. His inspirations don’t matter because who gives a shit about a bio when you don’t have any real credits. He has opened for “Rockin Magician” Micheal Trixx, Carol Pennington, the Disgruntled Clown and a bunch of other comedians who don’t matter. When he’s not doing comedy he enjoys traveling and spending time with his lovely wife Allison and his Weiner Dog Betty', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1781844446855-Kyle-Haunhorst.webp', '34R1xSji5u4ZORWkNetI') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('xd91cvpoc', 'D''Jaay BrownJohnson', 'Male', 'Black', 1000, 'djaaybrownjohnson', 'D’Jaay Brown Johnson is a rising star in comedy, bringing a fresh and relatable perspective to life’s darker moments. Young, broke, unapologetically gay, and charming as all get out; D’Jaay creates a connection that leaves audiences laughing and feeling lighter. D’Jaay has won contests, produced shows across Cleveland, and graced comedy clubs like the Columbus Funny Bone, Hilarities, and more.  You can catch a humorous tour of Cleveland with D''Jaay as your guide on The Funny Bus.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1781844504352-D_Jaay-BrownJohnson.webp', '34R1xSji5u4ZORWkNetI') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('w3ubi6c0l', 'James Earl Brassfield', 'Male', 'Black', 1000, 'jearlbrass', 'James Earl Brassfield Jr is an American comedian, actor, and writer. He has received much critical acclaim for his work in film since the 1990''s.  James is a frequent collaborator with Bob Seeholzer and Mike Polk Jr.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1781908882435-James-Earl-Brassfield.webp', '34R1xSji5u4ZORWkNetI') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('3ifz0rsja', 'Nicole Rossa', 'Female', 'White', 1000, 'viva_la_rossa_cle', 'Nicole has ADHD and is of Romani descent on her mother’s side. She reads tarot cards but does not play the tambourine. Her humor explores life’s challenges as an observant outsider who has never quite fit in– drawing special attention to the struggles of neurodivergent people, the working class, and economic outsiders.
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('uphmke6uz', 'Rich Ryan', 'Male', 'White', 1000, 'big_rich_n_funny', 'Rich Ryan is known as the white Big Rich, Richie, and the producer of Glass Box: A Comedy Showcase.  He is enormous, yet somehow not intimidating at all, probably because the writer of this bio has never attempted to steal his snacks.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1781917605632-Rich-Ryan.webp', '34R1xSji5u4ZORWkNetI') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('6l9foo57g', 'Dave Herron', 'Male', 'White', 1000, 'jackofalldaves', 'In addition to being Ohio''s fattest comedian, Dave Herron is one of the standout competitors in Roast Battle League Cleveland. A former RBL Cleveland champion and 2021 Rubber City Comedy Festival Best of Fest winner, Herron has built a reputation for sharp writing, relentless punchlines, and a fearless stage presence.  Dave has appeared on the countdown numerous times over the past three seasons and continues to be one of Cleveland''s top point earners. One of the league''s best dance partners, Herron is a slow moving, easy target who audiences love seeing roasted as he leads the league in lard.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1781844472322-Dave-Herron.webp', '34R1xSji5u4ZORWkNetI') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('utt4e7k9m', 'Cam Godfrey', 'Female', 'White', 1000, 'cammgodfrey', 'Cam Godfrey is a standup, sketch, and improv comedian from Cleveland, Ohio. She was a two-time Cleveland Scene Magazine nominee for Best Female Comedian, recipient of the Rookie of the Year Award at the 2023 Cleveland Comedy Awards, and “Loudest Girl” in her high school yearbook. 
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('7cuoz4q0t', 'Dan Handelman', 'Male', 'White', 1000, 'danmhandelman', 'Dan Myron Handelman is a comedian, musical composer, and aspiring glamour model from Lakewood Ohio. The son of a famous comedian and world class jazz singer, Dan spent most of his early years learning to mask the bad parts of his autism. He’s a former roast battle champion for the Ad Hominem Attack Show, now Roast Battle Cleveland. His brother is funnier than him', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1781844580930-Dan-Handelman.webp', '34R1xSji5u4ZORWkNetI') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('7675dllfn', 'Paul Runevitch', 'Male', 'White', 1000, '', 'Paul is a veteran actor and stand up comic from Cleveland best known for his role in Simply Tim''s play Dawg Pounded.  He is a frequent participant in local showcases and is old as hell, thus he does not have an Instagram account', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1781917365946-Paul-Runevitch.webp', '34R1xSji5u4ZORWkNetI') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('hf6wgvc52', 'Dion Skinner', 'Male', 'Black', 1000, '', '', FALSE, TRUE, 0, 0, 0, '', 'EzOfMEwWjCcQ7OF6lHb9') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('rkt6ab6a5', 'Bill Squire', 'Male', 'White', 1000, 'billsquire', 'In 2004, at age 22, Bill Squire was just your regular old excommunicated Mormon Missionary trying to find his way through life. Returning from a  two-year-long Mormon mission in the Philippines, Bill found his voice on stage traveling the country telling jokes as he relentlessly pursued stage time. 
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('if4e5on0y', 'Andre Myrie', 'Male', 'Black', 1000, 'andremyriecomedy', 'Andre Myrie is a first generation Jamaican/American comedian born and raised in the NY/NJ area. The result of this diverse upbringing has yielded an incredibly unique perspective which he feels that he can best share through the art form of comedy. His comedic style is simple; he speaks of observational truths in a storytelling format. He views this beautiful craft as a gift, which he does not take for granted. His first comedy special “Duck On a Pond” is now available on his YouTube Channel.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1781904796841-Andre-Myrie.webp', '34R1xSji5u4ZORWkNetI') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('yk14l1nwl', 'Angelo Menage', 'Male', 'White', 1000, 'lordangeelioagain', '​Angelo''s one-person show REMARKABLY APPARENT ran for one weekend at convergence-continuum, a small theatre in Tremont, Ohio. There is no existing evidence of this play ever happening. Aneglo''s done voiceover work for podcasts, notably The Storyworth Podcast (this episode wildly has received over 4.5 million view on Reels). Angelo performed a tight eight minutes and thirty seconds of hilarious standup comedy in the THE SMALL GARDEN, a live variety show in the 2022 BorderLight Fringe Festival. Angelo''s a comic yelling on stages that will allow it. He''s been a finalist in Bill Squire’s Comedy Contest, nominated for Best Short Form Joke in the 2025 Cleveland Comedy Awards, and was nominated for 2026 Comedian of the Year at the Cleveland Comedy Awards. He is also a graphic designer and the Art Director and Designer at Cleveland Review of Books. ', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1781905249105-Angelo-Menage.webp', '34R1xSji5u4ZORWkNetI') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('ro9affp2c', 'Bill Stone', 'Male', 'White', 1000, 'comicbillstone', 'Bill Stone is a hilariously funny stand-up comedian and entertainer. He is also a celebrated graphic designer and co-founder of BS Pro Design, creating digital designs and promotions for artists & venues from coast to coast. His laugh out loud comedy is something to be seen!  After only starting comedy at the ripe young age of 39, he quickly became a staple at The Funny Stop Comedy Club in Cuyahoga Falls, Ohio where he performed as a regular feature.  He now travels across the United States featuring and headlining at clubs and venues nationwide.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1781905693755-Bill-Stone.webp', '34R1xSji5u4ZORWkNetI') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('kchr4cbbk', 'Bob McClure', 'Male', 'White', 1000, 'bigmcclure', 'A native of Cleveland, Ohio, Bob began performing stand up after a move to Los Angeles in 2017. Since then he has traveled the country, performing in cities like Las Vegas, New York City, Boston, and more. He currently resides in Akron, Ohio with his wife, daughter, and their dog and cat.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1781905979836-Bob-McClure.webp', '34R1xSji5u4ZORWkNetI') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('6wnosa2qr', 'Jimmy Killius', 'Male', 'White', 1000, 'naughtylilcomedyboi_42069', 'Jimmy is the co-host of the Cleveland America podcast, Fight For Your Write at One Star Bar and Comedy Night at East End Bistro and Pub.  Jimmy is best known for getting boy-kissing drunk, but his battles are getting better and better every month.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1781909725030-Jimmy-Killius.webp', '34R1xSji5u4ZORWkNetI') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('3cpmou70e', 'Andrew Smith', '', '', 1000, '', '', FALSE, TRUE, 0, 0, 0, '', '3ld5tjmcr') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
