INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('2z1g28mbn', 'Brian Kenny', 'Male', 'White', 1000, 'iambriankenny', 'Brian Kenny is a gentleman, scholar, diabetic, and comedian that has appeared on Fox, can be seen on Hulu, and can be found yelling at audiences until they enjoy themselves all over this great country. He is a proud native of Cleveland, OH that has beautiful blue eyes, the traps of a God, and his beard game is on point. He co-produced Accidental Comedy Fest, performed at the 2014 Rock on the Range, and is a regular at the legendary Hilarities E 4th Theater in Cleveland, OH. He has opened for likes of Dave Attell, Norm McDonald, Dom Irrera, Kevin Pollack, Rob Schneider, Aisha Tyler, Joey "Coco" Diaz, and many more.  He can currently be heard on Ten Cent Beer Life, a Cleveland sports podcast.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1781906284495-Brian-Kenny.webp', '34R1xSji5u4ZORWkNetI') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('h6dr7pjqb', 'Cody Troutman', 'Male', 'White', 1000, 'cody.troutman', 'OKC''s Cody Troutman’s style is high energy, warm, and a little wacky.  Imagine if Willy Wonka told jokes instead of making candy.  Cody shines in tightly packed clubs and alt rooms, but has proven his ability to adapt his style to anything from rowdy dive bars to clean corporate gigs.  
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('z0buk2c9a', 'Calum Hunter', 'Male', 'White', 1000, '@itscalumhunter', '', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1782071267328-Calum-Hunter.webp', '6cqfva8oy') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('3rv9d10i6', 'Dar''Jon Bentley', 'Male', 'Black', 1000, 'iamdarjonbentley', 'Dar’Jon Bentley is a multi-hyphenated artist from Cleveland, Ohio. His talents range from acting, comedy, writing, teaching, and, depending on the drinks, even singing. Growing up, he aimed to make friends and family laugh; now it’s his mission. When he’s not performing, he is either at the gym, at the movies, or at home watching scary movies. Dar’Jon loves to talk about his culture, career, teaching, friends, and family.
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('5tnup5v1t', 'El Jordano Diablo', 'Male', 'White', 1000, 'eljordanodiablo', 'Jordan Patrick, better known as El Jordano Diablo, is 1/2 of the Fat Woke Boyz on Let The Hate Flow Through You, a specific general interest podcast.  He also co-hosted The Fattitude Era.  Prior to his comedic exploits, he promoted punk rock shows in Cleveland, OH.  Jordan just hit one year clean and sober.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1781907713507-El-Jordano-Diablo.webp', '34R1xSji5u4ZORWkNetI') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('hbi5ii4xl', 'Eulise Dickerson', 'Female', 'Black', 1000, '_eulisedickerson', 'Eulise Dickerson is a black female comic from Cleveland, Ohio known for her quick wit and ability to turn everyday situations into unexpected laughter. She has been performing comedy for 10+ years, with notable performances at the Cleveland Improv, Hilarities, and Funny Stop. This comedian is featured on Amazon Prime in the “You See Me” comedy series and has been a guest on The Michael Colyar Morning Show. She has shared stages with Correy Bell, Just Nesh, and Roy Wood Jr. just to name a few. Possessing a wide variety of comedic abilities she is a favorite among Gen Z and those who know the original Temptations. From Corporate to Private, She delivers!', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1781908125249-Eulise-Dickerson.webp', '34R1xSji5u4ZORWkNetI') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('qo93ur1h9', 'Jason Moliterno', 'Male', 'White', 1000, 'jasonmoliterno', 'Since first stepping on stage in 2012, comedian Jason Moliterno has delighted audiences with his clever observations, which he packs with smart wit and a dash of absurdity. Once described by a former teacher as a "slow-talking sage," this Youngstown, Ohio, native will either find a unique angle on an everyday subject or turn an unusual idea into something relatable. 
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('e8sb5a3zm', 'John Armstrong', 'Male', 'Black', 1000, 'johnarmstrongcomedy', 'John is from Cleveland. He has lived in the worst and best neighborhoods in and around the city, which gives him a unique outlook on the world. He uses this to talk about family, relationships, and current events. John has a quick wit and charismatic charm that jumps off the stage. One of the best and fastest-rising comedians in the city. ', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1781914233630-John-Armstrong.webp', '34R1xSji5u4ZORWkNetI') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('fwttwie7s', 'Justin Palko', 'Male', 'White', 1000, 'justinbejoking', 'Justin Palko is quickly making a name for himself in the Cleveland comedy scene. Now in just his second year of stand-up, he’s already racked up major recognition—earning a nomination for Rookie of the Year at the 2025 Cleveland Comedy Awards, as well as a nod for Best Comedian in Cleveland by Cleveland Scene Magazine. A regular on Roast Battle League, Justin is known for transforming personal trauma into sharply written stories that catch audiences off guard in the best way possible. With his fearless honesty and unpredictable punchlines, he''s one of the city’s most exciting up-and-coming voices.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1781914656920-Justin-Palko.webp', '34R1xSji5u4ZORWkNetI') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('h3bmb5byr', 'Logan Rishaw', 'Male', 'White', 1000, 'Loganrishaw', 'Logan Rishaw is a stand-up comedian and writer from Cleveland, Ohio. He has worked with many acts over the years including Kevin Nealon, Tom Papa, Christopher Titus, Ali Macofsky, and Brad Wenzel. Logan also co-hosted the podcast "What''s So Funny!", a deep dive into the works and lives of classic comedians. In 2020, he released a book of short fiction titled "Albert Catmus: Essays and Fiction".  Logan is a former three time Roast Battle Cleveland champion.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1781915738330-Logan-Rishaw.webp', '34R1xSji5u4ZORWkNetI') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('ea4j60sf6', 'Martin Ashworth', '', '', 1000, '', '', FALSE, TRUE, 0, 0, 0, '', 'P2ONL89ZfvaLZ1Ged5hC') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('29gexbpj2', 'Kaya Allyn', '', '', 1000, '', '', FALSE, TRUE, 0, 0, 0, '', '3ld5tjmcr') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('qdkhtrkwp', 'Martin Malloy', 'Male', 'White', 1000, 'clevelandcomedian', 'Marty just won the Golden Ticket on Kill Tony.  He lives with Schizo Affective Disorder, but he is medication compliant.  Marty is best known for his rapid fire one liners and his incessant merchandise pitches.  If you pay him and let him sell merch, he will do your show.  When he judges RBL shows, he generally goes by who buys the most merch, making him the most bribable judge in the league.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1781916387069-Martin-Malloy.webp', '34R1xSji5u4ZORWkNetI') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('yr91ma3xi', 'Noah Ryan', 'Male', 'White', 1000, 'noahryancomedy', 'Noah is a well-traveled comic based in Cleveland, Ohio. Originally hailing from Hartford, CT, Noah made his club debut at comix roadhouse at Mohican Sun where he has performed multiple times. Since then, Noah has performed at clubs, conventions, and showcases across the US including the Laugh Factory in Chicago and The Red Room, The Hartford Funny Bone, and The Loft. At home in Cleveland, Noah has cohosted a show monthly at Collision Bend, opened at the 2024 Cleveland Comedy Awards, and performed guest spots at Hiliarities. In the virtual world, Noah has found great success with his over 200 impressions. He has amassed over 600k followers between Instagram, Facebook, and TikTok and gained virality with his series “The Preschool Apprentice.” ', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1781917011910-Noah-Ryan.webp', '34R1xSji5u4ZORWkNetI') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('80fi5imeo', 'Mark-Anthony Lewis', 'Male', 'Black', 1000, 'Snarkanthony', '', FALSE, TRUE, 0, 0, 0, '', 'ao3s8vcv3') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('urasep8o9', 'Sean Jaundice', 'Male', 'White', 1000, 'seanjaundice', 'Sean is a tattoo artist at Voodoo Monkey Tattoos in Cleveland as well as the lead signer of L''Avorte, Church and State and The Struttin'' Cocks.  One time he hosted a comedy show in his basement that ended with a bunch of people chanting at a guy to poop in a basement toilet that was not connected to anything.  Sean did some work on Chris Paugh and Jeremy Sheer.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1781917996716-Sean-Jaundice.webp', '34R1xSji5u4ZORWkNetI') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('ta28bmlje', 'Timbuktu', 'Male', 'Black', 1000, 'timbuktu_31', 'Timbuktu is a comedian and DJ from Cleveland, OH.  He can be seen as part of the Lexx Vegas show, and is one of the few comics that can compete with Dave Herron in the weight department.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1781919015451-Timbuktu.webp', '34R1xSji5u4ZORWkNetI') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('hjce3nfaw', 'Olivia Bailey', 'Female', 'White', 1000, 'ob_comedy', 'Olivia Bailey is a comedian based in Washington, DC.  She performs all over DC and the surrounding areas.  Olivia has opened for Myq Kaplan, Benny Feldman and Caitlin Peluffo, to name a few.  Olivia has performed in several comedy festivals and won the JD Sidley Award for Best Writing at the 2025 Cleveland  Comedy Festival.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1781919728712-Olivia-Bailey.webp', '34R1xSji5u4ZORWkNetI') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('k9olvx02s', 'Rebecca Jaffe', 'Female', 'White', 1000, 'reb_jaffe', 'Accompanied by her ukulele,  Rebecca Jaffe expresses her whimsical point of view through standup and wacky songs.  When she''s not singing songs,  Rebecca can be found performing in sketch duo “Jaffe and Magy” or roast-battling.
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('58bh8xclu', 'Rich Greene', 'Male', 'Black', 1000, 'bigrichcomedy', 'Rich “Big Rich” Greene has a successful professional background of over 25 years in Outside Sales, Marketing, Product Management, Sales Management, Banking and Life Insurance Sales & Service!
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('37oa8ie1z', 'Sam Rossi', 'Male', 'White', 1000, 'sam_rossi_the_comedian', 'Sam Rossi has been described as a Norm Macdonald rip off, a Mitch Hedberg rip off, and most recently a Demetri Martin rip off! He is a Chicago-based comedian who has performed at Zanies, the Den Theater, and the Laugh Factory. In 2024, he won the Writer''s Award from the Cleveland Comedy Festival. And in 2025, he was voted the Most Underrated Comedian in Chicago by the Comedy Gazelle. His monopoly joke was also voted Joke of the Year by the Gazelle.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1781923562989-Sam-Rossi.webp', 'flb6n9upv') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('8m2hg7o64', 'Steven Prince', 'Male', 'White', 1000, 'princewatchshop', 'Based out of Cleveland, Ohio, Steven is the winner of four comedy contests and was nominated for Cleveland Comedy Awards in 2023 and 2024.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1781924329037-Steven-Prince.webp', '34R1xSji5u4ZORWkNetI') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('q7g26nuiu', 'Rachel McCartney', 'Female', 'White', 1000, 'rachelmcomedy', 'Rachel McCartney is a New York-based standup comedian and writer with a dark, personal, punchline-heavy style of humor. She has written TV-friendly jokes for Jonathan Corbblah on GSN''s Master Minds, TV-unfriendly jokes for Twitter (where she had over 80K followers before it became X), and several unproduced scripts that she swears are good — no, really! Her standup has appeared on Cracked Comedy Club''s YouTube channel, and in front of several road audiences who were waiting for her to bring up Gary Gulman.', FALSE, FALSE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1782058427767-Rachel-McCartney.webp', 'za2nHt1bzRQ0xgVRbCg2') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
