INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('hlc6xu04p', 'Yuki Nivez', 'Female', 'Asian', 1000, 'yukinivez', 'Yuki was Tokyo''s queen of deadpan comedy, now she''s becoming the international queen of deadpan comedy.  After sold-out shows at the Melbourne Comedy Festival and the Adelaide Fringe, Yuki is going to bite back to every "you should smile more" around the world! Yuki''s Roast Battles are as wickedly hilarious as her standup is. As the current Tokyo champion, no one has yet to made her even flinch on stage... challengers are welcome.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1782278659685-Yuki-Nivez.webp', 'NIeTzbnILTHvU69T33i3') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
