INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('nq18m2t9g', 'Emma Dalenberg', 'Female', 'White', 1000, 'emmadcomedy', 'A real heavy hitter, measuring up at 6 feet and one inch tall, Emma Dalenberg approaches her sets with good vibes and a genuine love to connect with audiences of all backgrounds. Beginning her career at 19 years old in Minneapolis Minnesota, she has since toured all over the United States and through 5 European countries, at venues ranging from packed theaters and clubs to small-town dive bars and bowling alleys. She is a paid regular at the nationally renowned Acme Comedy Club, was voted ''Racket Magazine’s 2022 Minnesota Comic to Watch,’ is twice featured in the Minnesota Star Tribune, has opened for Michael Che, Dave Attell, and Big Jay Oakerson, and most impressively, got deported from Germany in December of 2022. Now, Emma is focused on developing her act across the country, returning to Europe for her “American Cream” Tour, and is bringing Riffs, a stand-up jazz collaboration, to life with a group of notable jazz musicians and Minneapolis comics. Still in her mid-twenties, Emma has a lot of growing to do, but at least emotional growth doesn’t hurt your knees. She''s proud to have come up from her Midwestern trailer park beginnings and be a broke world traveler, with a good handful of subversive jokes, goofy stories, and intercultural observations to share', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1782091697986-Emma-Dalenberg.webp', 'za2nHt1bzRQ0xgVRbCg2') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('85369zmt8', 'Stephen Taylor', 'Male', 'White', 1000, 'formerlyfatstephen', 'Originally a Louisiana native, Stephen moved to Kansas City to escape his traditional southern roots. He''s a fast rising talent in the region that has worked with comics like Theo Von, Karlous Miller, and Laurie Kilmartin. A former teacher, reformed preacher, and political operative, Stephen combines his unique perspective with some interesting stories and some sweet southern charm and headlines at your favorite clubs, colleges, and bars across the country. He has been featured on The Breakfast Club, The New York Post, and at San Fransisco Sketchfest. He was recently awarded best performer at the 2023 Cleveland Comedy Festival, is the co-founder of the Barrel of the Bottoms studio in Kansas City, and the co-host of the Set to Destroy Podcast. ', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1782092186900-Stephen-Taylor.webp', '34R1xSji5u4ZORWkNetI') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
