INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('wpdyf7sob', 'Okpants', 'Male', 'White', 1000, 'okpants', 'Okpants is a small business owner, graphic designer and comedian from Cleveland, OH.  He is a co-host of the Cleveland America podcast, and a frequent host at Don''t Tell and at his own bar Old ''86, which in its short time in Gordon Square has become the post show destination for many.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1782172849121-Okpants.webp', '34R1xSji5u4ZORWkNetI') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('z4r4brfq9', 'Rob Stant', 'Male', 'White', 1000, 'robstantcomedy', 'Rob Stant is a stand up comedian based just outside of Philadelphia. He was 2nd runner up for Phillys Phunniest and has found great success on social media amassing a substantial amount of followers on Tik Tok and Instagram. Rob is best known for his observational humor and stories about his wife and family, but also enjoys poking fun at himself and the audience. You can watch his special “Bobby Boy” on YouTube and listen to his podcast “Two in the Stink” on all streaming platforms.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1782177680872-Rob-Stant.webp', 'cOWxAMnJvIjbYvcO7Emd') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('59grlvqt0', 'Mike Niedosik', 'Male', 'White', 1000, 'doslaflare', 'Mike Niedosik is a comedian from Philadelphia, PA', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1782178095593-Mike-Niedosik.webp', '34R1xSji5u4ZORWkNetI') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
