INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('s1sgpqsam', 'Ali Feet', 'Female', 'White', 1000, 'alifeetcomedy', 'Since beginning her stand-up career in New York City, Ali Feet has become a familiar presence at comedy clubs, roast battles, and open mics throughout the city. Originally from both Long Island and Staten Island, she now balances life as a comedian with a career in fashion, giving her the unique ability to critique both your outfit and your personality in the same sentence.
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('5eioye3vb', 'Rob Rego', 'Male', 'White', 1000, 'almostrobrego', '', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1782256683718-Rob-Rego.webp', 'za2nHt1bzRQ0xgVRbCg2') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('6w7cq05ze', 'Anjelica Scannura', 'Female', 'White', 1000, 'scanooch', 'Anjelica Scannura is a 2025 Just For Laughs New Face of Stand-Up, and the first Canadian woman to win the Boston Comedy Festival. She recently also won the Jersey City Comedy Festival, and has performed on iconic stages including Massey Hall and The Wilbur. Her debut comedy EP with JFL Originals can be heard on SiriusXM, and she’s also recorded for the Winnipeg Comedy Festival and CBC’s Laugh Out Loud multiple times. She has opened for Shane Gillis, Joe List, Stavros, Rachel Feinstein, and Jay Pharoah. On screen, Anjelica has appeared in Disney’s Camp Rock, CTV’s Satisfaction, CBC’s Frankie Drake Mysteries, and Netflix’s Little Italy. Her Don’t Tell Comedy set can be viewed online, and she recently taped Roast Battle Canada at JFL Montreal, where Russell Peters called her battle the top 10 of all time. Anjelica has been performing at leading comedy festivals across North America and will next be appearing at Skankfest.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1782266074764-Anjelica-Scannura.webp', 'za2nHt1bzRQ0xgVRbCg2') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('xhv5bjz2p', 'Dezhawn France', 'Male', 'Black', 1000, 'dezhawnfrance', 'Dezhawn France is a 27 year old stand up comic from Mansfield, Ohio he’s been doing stand up for 10 years but if you ask him he’ll say “10 years consistently but the first time I did it was on my 18th birthday then I just did it sporadically.” he has performed all over northeast Ohio mostly Akron and Cleveland BUT other places too like one time in Detroit and a few times in New York. He’s one funny little fella he’s been told that by men and women alike they always emphasize the little more than funny. He’s opened for prominent comedians such as Brandon Wardell, Lynne Koplitz, Jermaine Fowler, Gavin Matts Jak Knight, Zack Fox, Sahib Singh, Ramon Rivas and more. He’s a funny dude.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1782267669089-Dezhawn-France.webp', '34R1xSji5u4ZORWkNetI') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('0la50l3pj', 'Robert Coleman Jr', 'Male', 'Black', 1000, 'rufunnyrob', 'Experience the comedy genius of Robert Coleman, a stand-up comedian known for his sharp wit and relatable humor. With a unique style that keeps audiences laughing, Robert is the World Series of Comedy Winner 2025. Don''t miss the chance to witness his side-splitting jokes and captivating storytelling.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1782267838368-Robert-Coleman-Jr.webp', '34R1xSji5u4ZORWkNetI') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('fvaaeal2y', 'Marv Conner', 'Male', 'White', 1000, 'marvin.conner', 'Marv has been doing comedy since 1998 along with a great teaching career. He has retired from teaching and is ready to hit the road making people laugh.  Marv is one of the few Lawful Good comedians in existence.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1782268804786-Marv-Conner.webp', '34R1xSji5u4ZORWkNetI') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('r5pkek9ka', 'Kristin Galewood', 'Female', 'White', 1000, 'adventure_nature_hiker', 'Kristin Galewood - Kristin has been performing stand up and sketch comedy since 2009.  Her love of dinosaurs and Disney masks a stone cold killer who has dominated the Cleveland area Roast Battles.  She traveled to Branson not to specifically upset Yakov Smirnoff with her brand of dark, absurd humor, but she did.  ', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1782269404421-Kristin-Galewood.webp', '34R1xSji5u4ZORWkNetI') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
