INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('tatsr34t0', 'Monica Hager', 'Female', 'White', 1000, 'bitsofmonica', 'She''s bold, she''s referential, she''s the bravest comedienne in all of Northeast Ohio. Everybody''s talking about Monica Hager. She''s appeared on showcases all throughout the NEOhio area, opened for comic sensation Tanya Lee Davis, and is coming off a successful stint at the Sixth City Comedy festival. A unique voice in a sea of mimicry, she''s able to touch on the subjects of the day with wit and pathos. Drawing her material from her struggles with autism, a complicated family tapestry, and the lived realities of transgender life, she''s surprisingly relatable.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1782600410621-Monica-Hager.webp', '34R1xSji5u4ZORWkNetI') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
