INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('hwf0srulv', 'Harold Patrick', 'Male', 'White', 1000, 'haroldpatrick430', 'Born and raised in Chicago, Harold started doing Comedy in 2022. Co-hosts a weekly open mic on Tuesdays where the audience members can write roasts about the comics on-stage. He performs all over Chicago and surrounding suburbs and has done stand-up in Austin and Memphis with those good ole folk.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1782605194170-Harold-Patrick.webp', 'flb6n9upv') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('2h3xg5ix5', 'AJ DiCosimo', 'Male', 'White', 1000, 'ajdicosimo', 'AJ DiCosimo is a writer and humorist who lives in Cleveland, Ohio. His work has appeared in MAD Magazine, Spin, The New Yorker’s Shouts & Murmurs, Syfy, and Weekly Humorist. He honestly doesn’t know who would win in a fight between 100 men and a gorilla, but he certainly knows who he is rooting for.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1782605382885-AJ-DiCosimo.webp', '34R1xSji5u4ZORWkNetI') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('1lbfbpyru', 'Justin Golak', 'Male', 'White', 1000, 'justingolak', 'Justin Golak’s comedy offers a brutal but thoughtful take on all the things your mom told you not to talk about in polite conversation. Delivered with just the right amount of infamous Golak charm, he’ll only leave you with a small urge to punch him in the face and a more pressing one to hear what he said again. Tapped as Columbus Alive newspaper’s 2012 entertainer to watch, Golak has taken stages across the country. If you enjoy being the thinking type who also appreciates a well-timed dick joke, this dude’s for you.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1782606832721-Justin-Golak.webp', 'flb6n9upv') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('12a5ci81d', 'Ryley Nezballa', 'Male', 'White', 1000, 'ryleyjohnphilip', 'Ryley is a log cabin republican and server at Hilarities.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1782607590612-Ryley-Nezballa.webp', '34R1xSji5u4ZORWkNetI') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
