INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('pmlzxua14', 'Elliot Burns', 'Male', 'White', 1000, 'ellsworth_cars', 'Elliott Burns is one of Pittsburgh''s (You didn''t see that coming) funniest and most likeable stand-up Comedians. Making people laugh is a personal matter for Elliott. He''s passionate about creating funny, unique, engaging content and putting on energetic, hilarious stand up performances.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1782608173660-Elliot-Burns.webp', 'AHjyLmocgSHDrs8Bj4fd') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('1m0fuaf2q', 'Dwayne Duke', 'Male', 'Black', 1000, 'funnydwayne', 'Originally from Cleveland, Ohio, Dwayne Duke began performing in Tampa, Florida. His humor is drawn from personal anecdotes, observations of the world around him, and his own vivid imagination.His act takes you on a journey through adventures with his Baptist family, and his world wearied observations on popular culture. He refused to let the boundaries of polite society dictate his lifestyle, and you’ll yearn to hear which taboo he’ll tackle next.
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('xtozfz3y8', 'Dante Pizzini', 'Male', 'White', 1000, '', 'Dante is busy playing Shin Megami Tensai V: Vengeance', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1782609271500-Dante-Pizzini.webp', '34R1xSji5u4ZORWkNetI') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('hlvkxhj13', 'Courtney Peterson', 'Female', 'White', 1000, 'malortney', 'Courtney is a local Chicago Comedian and the newest host for Chicago’s longest running open mic: Power Hour! Her highlights include opening for Maria Bamford and Andrew Santino.  She is a former producer of Roast Battle Chicago.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1782609503567-Courtney-Peterson.webp', 'flb6n9upv') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
