INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('evr9yw2py', 'Dima Watermelon', 'Male', 'White', 1000, 'dimawatermelon', 'My name is Dima Watermelon and I love to make people laugh. My comedic style is a mix of absurdity, social commentary and some allegedly inappropriate jokes. Self-proclaimed inventor of mumble comedy. And yes, Watermelon is indeed my real surname, simply translated into English.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1782666483050-Dima-Watermelon.webp', '4w8gi6ahm') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
