INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('urw42wwae', 'Dan Finegold', 'Male', 'White', 1000, 'dan_finegold', 'Dan Finegold is a prolific roaster with the greatest record in the game of just having fun no matter who wins. He is excited to be participating in RBL where he hopes to learn more about whether or not he seems gay.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1782763239605-Dan-Finegold.webp', 'za2nHt1bzRQ0xgVRbCg2') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
