INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('ul4n5xwm4', 'Shelley Gruenberg', 'Female', 'White', 1000, 'notshelleyjo', 'Shelley Jo Gruenberg is Atlanta’s roast battle champion! With a 20–1 record within the RBL! Tune into her podcast “shoot him- an advice podcast” and catch her debut special releasing later this year “Mrs. Worldwide." ￼ Shelley loves hotdogs, monster energy drinks, and purses shaped like animals.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1784351123132-Shelley-Gruenberg.webp', 'ltoAG5QnUdBP0cospB3l') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
