INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('xvk3aeewk', 'Gary Walsh', 'Male', 'White', 1000, 'gw_comedy', 'Gary Walsh is a comedian and the creator of 2 successful comedy nights. A comedy competition called “Clap Back to Reality” and a Pro comedy night called “You About Comedy” which takes place at the Camden Etcetera Theatre and other venues. He gigs regularly with London teams such as Roast Battle UK, Comedy in Your Eye and Tall Tales & Cocktails and he has a regular working relationship with teams based outside of London such as People’s Comedy, Mates Rates Comedy & Solent Comedy.Additionally, Gary is a regular DJ/Tech at Comedy Freaks and gigs here regularly. He’s also beat the gong at The Comedy Store none of which I’ve mentioned above are open mic comedy.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1785010986618-Gary-Walsh.webp', 'P2ONL89ZfvaLZ1Ged5hC') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
