INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('0nsib7k55', 'Kevin Kellam', 'Male', 'White', 1000, 'kevkellam6', 'You can catch Kevin ON AIR on the most influential alternative rock radio station, Q101 sharing ridiculous takes and saying silly things before you hear that song you love from Green Day. 
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('zm4pQiFcLgBwS4kyrPOG', 'Corinne Tryon', 'Female', 'White', 1000, 'tryoncorinne', 'Corinne Tryon is a born and raised Hartford County resident and has been doing stand-up comedy and roasting since 2023. Being the oldest sister to two younger brothers though, she''s technically been doing both her entire life. Corinne is a self-proclaimed jack of all trades and a master of absolutely none but she has proven it true, it IS oftentimes better than a master of one. She joined the Roast Battle Hartford team in 2025 and has since become part Roaster, Producer, Editor, Graphic Designer, Film/AV crew and Dan Wickes'' appointed Hartford RBL website content slave. Corinne has battled at The Elbow Room, NYCC Stamford, and Grove 34 with a pretty strong winning heavy ratio, but has come up short on gaining any RBL points for the Hartford team so far this season. Will she make a comeback in the last half? Come back to this bio in December 2026 to find out.  ', FALSE, TRUE, 2, 1, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1780438644394-Corinne-Tryon.webp', 'dOfXYBu8N1KovWgOiLZ5') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('G0XvJrNNU4U7HqRDvxqS', 'Robbie Goodwin', 'Male', 'White', 1000, 'robbiegoodwin', 'Robbie Goodwin is a New York-based comedian, podcaster, actor, and writer who has appeared on The Howard Stern Show and Schtick or Treat with Mark Normand on Tubi. He has judged Roast Battle at The Comedy Store, Cobb’s Comedy Club, New York Comedy Club, and Roast Battle Chicago. Robbie started his stand-up career in the San Francisco and Boston scenes before performing across Los Angeles and New York, bringing sharp jokes, offbeat instincts, and Tony soprano impressions to every set.', TRUE, TRUE, 1, 2, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1789429415639-robbie-goodwin.webp', 'za2nHt1bzRQ0xgVRbCg2') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('ZVBztDWtrMUOr54tNJgA', 'Abbey Vollman', 'Female', 'White', 1000, 'abbeyvcomedy', 'Abbey Vollman is the nicest-mean girl from Houston, Texas and a comedian based in New York City.  Abbey finds life upsetting and confusing, so she uses her stand up comedy to figure out what the hell is going on! Abbey’s comedy begs the questions: “Why are people the way that they are?” and “Why do they make her so mad?” Yeah it’s true that she’s never taken a deep breath, but she has opened for killer acts like Iliza Shlesinger, and Nick Thune. Abbey has been featured on the Amazon Prime show “Clay’s Feast”, and recently starred in two buzzed about feature films expected to be released in 2026. You can catch Abbey roasting and performing all over NYC.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1782943458064-Abbey-Vollman.webp', 'za2nHt1bzRQ0xgVRbCg2') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('jqmp7x9v5', 'Brandon Petri', 'Male', 'White', 1000, 'thebrandonpetri', 'Cleveland''s own Brandon Petri, blends whimsicality and pathos with dark humor to create a regrettably relatable standup presentation. Brandon has been seen at the Cleveland Comedy Festival, Rubber City Comedy Festival, and the Flagship Comedy Festival. He is a regular of Funny Farm Comedy Club, and a three time Roast Battle Cleveland champion. Audiences can look forward to a witty, yet socially awkward experience, and the knowledge they have helped to feed a starving man child with their attendance', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1780500093835-Brandon-Petri.webp', '34R1xSji5u4ZORWkNetI') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('4mx2kxs42', 'James Allen', 'Male', 'White', 1000, 'javanomad', 'After establishing a decades-long professional career in Japan with a happy family, James has now made the most sensible decision for his next step: Comedy roast battle. A handsome silver fox with a filthy tongue, James is rushing into the Tokyo scene!', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1791126019128-battler.webp', 'NIeTzbnILTHvU69T33i3') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('tpq81gkgh', 'Haru', 'Female', 'Asian', 1000, 'haru_mia_a', 'A Trilingual force from Inner Mongolia and runner-up of the 2026 King of Kanto Competition, Haru is a rare kind of Chinese woman... quiet. But the quietest comedians always have the most devastating roast jokes...', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1791126326397-battler.webp', 'NIeTzbnILTHvU69T33i3') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('ykm3pzh4s', 'Ryotaro', 'Male', 'Asian', 1000, 'noflow.ryo', 'Champion of the 2026 King of Kanto Standup Comedy Competition, Ryotaro is no flow but not slow! After a smashing debut battle, he''s now ready to take on more opponents.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1790829552959-battler.webp', 'NIeTzbnILTHvU69T33i3') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
