INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('w759w09am', 'Tom Sarabok', 'Male', 'White', 1000, 'tomsarabok', 'Tom Sarabok is a self-absorbed comedian from Pittsburgh, now based in Bushwick, Brooklyn where he hits on girls with septum piercings at dive bars even though he works in finance. Tom is “known” online for his sketches, such as when he plays a Yinzer Nurse on The Pitt and pretends to have a deeper connection to his hometown, or provides LooksMinning tutorials where he somehow makes himself look even uglier. Tom also hosts a podcast he hasn’t produced in months called Riffipedia, where himself and guests riff on random Wikipedia articles.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1785938183844-tom-sarabok.webp', 'za2nHt1bzRQ0xgVRbCg2') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('3pZ9ZGP0Z4GmdhU5ftA7', 'Joe Levy', 'Male', 'White', 1000, 'thejoelevy', 'Joe is a 25 year old comic from Brooklyn who dreams of one day making it out of his parent’s house. While he might look like a big Jew on the outside, just wait till you hear his voice, that’ll really give it away. Joe has a unique comedy styling that has the ability to make the audience either really laugh or really unsure what he is doing. You are either with him or against but no matter what it will be a good time.', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1781844309129-Joe-Levy-___.webp', 'za2nHt1bzRQ0xgVRbCg2') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('s238nkclk', 'Sara Shipley', 'Female', 'White', 1000, 'funnysarashipley', 'Sara Shipley is a NYC comedian originally from Rochester, NY. In 2021, sara won the Funniest Person in Rochester competition, which has come to haunt her in the roast battle arena many times over. Sara grew up the youngest in a big Italian family where taunting, yelling, crying, and roasting each other was just called Christmas. If you think about it, roast battle is just one big homophobic, sexist, racist, love letter to a simpler time, when Santa was real and her gram was still alive. ', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1781843563224-Sara-Shipley.webp', 'za2nHt1bzRQ0xgVRbCg2') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
