INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('9xcOwADYQXBDBKEWivOv', 'Pauline Murphy', 'Female', 'White', 1000, 'whiskeyburrito', 'Pauline Murphy is a stand-up comic born and raised out of Staten Island, New York.  She started roasting over a decade ago here in New York City and had been featured on Roastmasters multiple times.  When she''s not working with dogs, she can be found at gigs all over the five boroughs and beyond.  To date, her favorite gig has been opening for Jason Mewes.', FALSE, TRUE, 1, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1782942925100-Pauline-Murphy.webp', 'za2nHt1bzRQ0xgVRbCg2') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
