INSERT INTO public.battlers (id, name, gender, race, rating, instagram, bio, show_on_homepage, show_on_city_page, wins, losses, draws, image_url, city_id) VALUES ('08w1thk3c', 'Sarah Steiner', '', '', 1000, 'amifunnyyetmom', 'Say hello to Sarah Steiner, the goth mom you never knew you needed. Just like any mother she loves you all, but that doesn’t mean she always likes you. With roasts that focus on wordplay and an unshakable core, Sarah is ready for anything that comes her way. ', FALSE, TRUE, 0, 0, 0, 'https://rbl-ny-992338142544-us-east-1-an.s3.us-east-1.amazonaws.com/processed/webp/1791220918006-battler.webp', 'EsB8d3igfe3Vc6nV6VsN') ON CONFLICT (id) DO UPDATE SET wins = EXCLUDED.wins, losses = EXCLUDED.losses, draws = EXCLUDED.draws, rating = EXCLUDED.rating;
